{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.access_override_company_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM user_company_roles ucr
     WHERE ucr.user_id = NEW.user_id AND ucr.company_id = NEW.company_id
  ) THEN
    RAISE EXCEPTION 'ACCESS_OVERRIDE_COMPANY_ROLE_REQUIRED' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.apply_supplier_tracking_defaults_to_container()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    DECLARE
      default_shop text;
      default_agent varchar(100);
      default_duty numeric(15,2);
      old_default_shop text;
      old_default_agent varchar(100);
      old_default_duty numeric(15,2);
    BEGIN
      IF TG_OP = 'INSERT' THEN
        SELECT COALESCE(NULLIF(BTRIM(d.shop_name), ''), l.name),
               d.agent_name, d.duty_fee
          INTO default_shop, default_agent, default_duty
          FROM supplier_tracking_defaults d
          LEFT JOIN locations l
            ON l.id = d.location_id AND l.company_id = d.company_id
           AND l.active = true AND l.deleted_at IS NULL
         WHERE d.company_id = NEW.company_id
           AND d.supplier_id = NEW.supplier_id AND d.active = true
         LIMIT 1;

        IF COALESCE(BTRIM(NEW.shop_name), '') = ''
           AND COALESCE(BTRIM(default_shop), '') <> '' THEN
          NEW.shop_name := BTRIM(default_shop);
        END IF;
        IF COALESCE(BTRIM(NEW.agent), '') = ''
           AND COALESCE(BTRIM(default_agent), '') <> '' THEN
          NEW.agent := BTRIM(default_agent);
        END IF;
        -- Explicit 0 is a valid duty, not an empty value.
        IF NEW.duty_fee IS NULL AND default_duty IS NOT NULL THEN
          NEW.duty_fee := default_duty;
        END IF;

      ELSIF NEW.company_id IS DISTINCT FROM OLD.company_id
         OR NEW.supplier_id IS DISTINCT FROM OLD.supplier_id THEN
        SELECT COALESCE(NULLIF(BTRIM(d.shop_name), ''), l.name),
               d.agent_name, d.duty_fee
          INTO old_default_shop, old_default_agent, old_default_duty
          FROM supplier_tracking_defaults d
          LEFT JOIN locations l
            ON l.id = d.location_id AND l.company_id = d.company_id
           AND l.active = true AND l.deleted_at IS NULL
         WHERE d.company_id = OLD.company_id
           AND d.supplier_id = OLD.supplier_id AND d.active = true
         LIMIT 1;
        SELECT COALESCE(NULLIF(BTRIM(d.shop_name), ''), l.name),
               d.agent_name, d.duty_fee
          INTO default_shop, default_agent, default_duty
          FROM supplier_tracking_defaults d
          LEFT JOIN locations l
            ON l.id = d.location_id AND l.company_id = d.company_id
           AND l.active = true AND l.deleted_at IS NULL
         WHERE d.company_id = NEW.company_id
           AND d.supplier_id = NEW.supplier_id AND d.active = true
         LIMIT 1;

        IF COALESCE(BTRIM(NEW.shop_name), '') = ''
           OR (COALESCE(BTRIM(old_default_shop), '') <> ''
               AND BTRIM(NEW.shop_name) = BTRIM(old_default_shop)) THEN
          NEW.shop_name := NULLIF(BTRIM(default_shop), '');
        END IF;
        IF COALESCE(BTRIM(NEW.agent), '') = ''
           OR (COALESCE(BTRIM(old_default_agent), '') <> ''
               AND BTRIM(NEW.agent) = BTRIM(old_default_agent)) THEN
          NEW.agent := NULLIF(BTRIM(default_agent), '');
        END IF;
        IF NEW.duty_fee IS NULL
           OR (old_default_duty IS NOT NULL AND NEW.duty_fee = old_default_duty) THEN
          NEW.duty_fee := default_duty;
        END IF;
      END IF;

      RETURN NEW;
    END;
    $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.assign_supplier_company_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  resolved_company_id INTEGER;
  fallback_parent_count INTEGER;
BEGIN
  IF NEW.company_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT CASE
           WHEN value ~ '^[1-9][0-9]*$' THEN value::INTEGER
           ELSE NULL
         END
    INTO resolved_company_id
    FROM system_settings
   WHERE key = 'parentCompanyId'
   LIMIT 1;

  IF resolved_company_id IS NULL THEN
    SELECT COUNT(*)::INTEGER
      INTO fallback_parent_count
      FROM companies
     WHERE active = TRUE
       AND company_type = 'erp'
       AND parent_company_id IS NULL;

    IF fallback_parent_count = 1 THEN
      SELECT id
        INTO resolved_company_id
        FROM companies
       WHERE active = TRUE
         AND company_type = 'erp'
         AND parent_company_id IS NULL
       LIMIT 1;
    ELSE
      RAISE EXCEPTION
        'Supplier company ownership is required; configure system_settings.parentCompanyId';
    END IF;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM companies WHERE id = resolved_company_id) THEN
    RAISE EXCEPTION 'Configured supplier parent company % does not exist', resolved_company_id;
  END IF;

  NEW.company_id := resolved_company_id;
  RETURN NEW;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.copy_customer_order_bale_scanned_at_to_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
        BEGIN
          IF NEW.scanned_at IS NULL THEN
            SELECT cob.scanned_at
            INTO NEW.scanned_at
            FROM public.customer_order_bales cob
            WHERE cob.id = NEW.original_id
            LIMIT 1;
          END IF;
          RETURN NEW;
        END;
        $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_allocation_eligibility_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  active_center BOOLEAN;
  parent_voucher RECORD;
  daybook_type TEXT;
  daybook_reference TEXT;
  daybook_reference_id INTEGER;
  daybook_amount NUMERIC;
  daybook_usd NUMERIC;
BEGIN
  SELECT active INTO active_center FROM cost_centers
    WHERE id=NEW.cost_center_id AND company_id=NEW.company_id;
  IF active_center IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'Cannot allocate to missing or archived cost center';
  END IF;

  IF NEW.voucher_entry_id IS NOT NULL THEN
    SELECT la.account_type, la.code AS account_code, ve.debit_amount, ve.credit_amount, v.voucher_number, v.source_module, v.optional, v.deleted_at
      INTO parent_voucher
    FROM voucher_entries ve
    JOIN vouchers v ON v.id=ve.voucher_id
    LEFT JOIN ledger_accounts la ON la.id=ve.ledger_account_id AND la.company_id=ve.company_id
    WHERE ve.id=NEW.voucher_entry_id AND ve.company_id=NEW.company_id
      AND v.company_id=NEW.company_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Voucher entry is unavailable for cost allocation';
    END IF;
    IF parent_voucher.voucher_number IS NULL OR parent_voucher.deleted_at IS NOT NULL
       OR parent_voucher.optional = TRUE
       OR parent_voucher.voucher_number LIKE 'GC-%'
       OR parent_voucher.voucher_number LIKE 'MIG-%'
       OR parent_voucher.source_module = 'SP_MIGRATION_READONLY'
       OR upper(coalesce(parent_voucher.source_module,'')) LIKE 'INTERCOMPANY%'
       OR cost_center_voucher_in_reversal_pair(
         (SELECT ve.voucher_id FROM voucher_entries ve WHERE ve.id=NEW.voucher_entry_id)
       ) THEN
      RAISE EXCEPTION 'Protected, optional, deleted or migrated vouchers cannot be allocated';
    END IF;
    IF upper(btrim(parent_voucher.account_type)) IN ('EXPENSE','DIRECT EXPENSE','INDIRECT EXPENSE') THEN
      IF NEW.cost_treatment <> 'EXPENSE' THEN
        RAISE EXCEPTION 'Expense ledger lines must keep EXPENSE cost treatment';
      END IF;
    ELSIF upper(btrim(parent_voucher.account_type)) = 'ASSET' THEN
      IF parent_voucher.account_code NOT IN (
        'FACTORY_RAW_MATERIAL_STOCK','FACTORY_WIP','FACTORY_FINISHED_GOODS'
      ) OR coalesce(parent_voucher.debit_amount,0) <= 0
        OR coalesce(parent_voucher.credit_amount,0) <> 0
        OR NEW.cost_treatment <> 'INVENTORY_COST' THEN
        RAISE EXCEPTION 'Only factory inventory stock accounts may receive INVENTORY_COST treatment';
      END IF;
    ELSE
      RAISE EXCEPTION 'Only expense or asset ledger lines may have cost center allocations';
    END IF;
  ELSE
    SELECT tx_type, reference_table, reference_id, amount_currency, amount_usd
      INTO daybook_type, daybook_reference, daybook_reference_id, daybook_amount, daybook_usd
      FROM factory_daybook_entries
    WHERE id=NEW.factory_daybook_entry_id AND company_id=NEW.company_id;
    -- No double-counting of Factory payment, journal, sale, or POS expense
    -- daybook mirrors. Future supported standalone expense types are explicit.
    IF daybook_type IS NULL OR daybook_type NOT IN
       ('EXPENSE', 'OPERATING_EXPENSE', 'FACTORY_EXPENSE')
       OR nullif(btrim(coalesce(daybook_reference,'')),'') IS NOT NULL
       OR daybook_reference_id IS NOT NULL
       OR coalesce(daybook_amount,0)<=0 OR coalesce(daybook_usd,-1)<0
       OR NEW.cost_treatment <> 'EXPENSE' THEN
      RAISE EXCEPTION 'Factory daybook source is not a standalone expense';
    END IF;
  END IF;
  RETURN NEW;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_allocations_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  source_company_id INTEGER;
  source_currency VARCHAR(10);
  source_native NUMERIC(20,6);
  source_base NUMERIC(20,6);
  previous_native NUMERIC(20,6);
  previous_base NUMERIC(20,6);
BEGIN
  PERFORM pg_advisory_xact_lock(721031, NEW.company_id);

  IF NEW.base_currency <> 'USD' THEN
    RAISE EXCEPTION 'Phase 1 cost center base snapshots must use USD';
  END IF;

  IF TG_OP = 'UPDATE' AND (
    NEW.company_id IS DISTINCT FROM OLD.company_id
    OR NEW.voucher_entry_id IS DISTINCT FROM OLD.voucher_entry_id
    OR NEW.factory_daybook_entry_id IS DISTINCT FROM OLD.factory_daybook_entry_id
  ) THEN
    RAISE EXCEPTION 'Allocation company and source are immutable; reallocate instead';
  END IF;

  IF NEW.voucher_entry_id IS NOT NULL THEN
    SELECT ve.company_id,
      COALESCE(ve.transaction_currency, v.currency, 'USD'),
      GREATEST(
        abs(COALESCE(ve.transaction_debit_amount, ve.debit_amount, 0)),
        abs(COALESCE(ve.transaction_credit_amount, ve.credit_amount, 0))
      ),
      GREATEST(
        abs(COALESCE(ve.base_debit_amount, ve.debit_amount, 0)),
        abs(COALESCE(ve.base_credit_amount, ve.credit_amount, 0))
      )
      INTO source_company_id, source_currency, source_native, source_base
    FROM voucher_entries ve
    JOIN vouchers v ON v.id = ve.voucher_id
    WHERE ve.id = NEW.voucher_entry_id
      AND v.deleted_at IS NULL
    FOR SHARE OF ve, v;
  ELSE
    SELECT f.company_id, f.currency_code,
      abs(f.amount_currency), abs(f.amount_usd)
      INTO source_company_id, source_currency, source_native, source_base
    FROM factory_daybook_entries f
    WHERE f.id = NEW.factory_daybook_entry_id
    FOR SHARE;
  END IF;

  IF source_company_id IS NULL OR source_company_id <> NEW.company_id THEN
    RAISE EXCEPTION 'Cost center source must exist in the same company';
  END IF;
  IF upper(btrim(NEW.currency)) <> upper(btrim(source_currency)) THEN
    RAISE EXCEPTION 'Cost center allocation currency differs from source currency';
  END IF;

  SELECT COALESCE(sum(amount_native), 0), COALESCE(sum(amount_base), 0)
    INTO previous_native, previous_base
  FROM cost_center_allocations
  WHERE company_id = NEW.company_id
    AND id <> NEW.id
    AND (
      (NEW.voucher_entry_id IS NOT NULL AND voucher_entry_id = NEW.voucher_entry_id)
      OR (NEW.factory_daybook_entry_id IS NOT NULL AND factory_daybook_entry_id = NEW.factory_daybook_entry_id)
    );

  IF source_native IS NULL OR source_base IS NULL
     OR previous_native + NEW.amount_native > source_native
     OR previous_base + NEW.amount_base > source_base THEN
    RAISE EXCEPTION 'Cost center allocations exceed the source transaction amount';
  END IF;

  RETURN NEW;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_archive_children_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.active = TRUE AND NEW.active = FALSE AND EXISTS (
      SELECT 1 FROM cost_centers WHERE company_id=NEW.company_id
      AND parent_id=NEW.id AND active=TRUE
    ) THEN
    RAISE EXCEPTION 'Archive active child cost centers first';
  END IF;
  RETURN NEW;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_auto_after_daybook_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM cost_center_auto_rules r
      WHERE r.company_id = NEW.company_id AND r.source_kind = 'FACTORY_DAYBOOK' AND r.active
    ) THEN
      RETURN NULL;
    END IF;
    PERFORM cost_center_auto_apply_factory_daybook(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    PERFORM cost_center_auto_record_failure(NEW.company_id, 'FACTORY_DAYBOOK', NEW.id, SQLERRM);
    RAISE WARNING 'Cost center auto allocation skipped factory daybook entry %: %', NEW.id, SQLERRM;
  END;
  RETURN NULL;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_auto_after_voucher_entry_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM cost_center_auto_rules r
      WHERE r.company_id = NEW.company_id AND r.source_kind = 'VOUCHER_ENTRY' AND r.active
    ) THEN
      RETURN NULL;
    END IF;
    PERFORM cost_center_auto_apply_voucher_entry(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    PERFORM cost_center_auto_record_failure(NEW.company_id, 'VOUCHER_ENTRY', NEW.id, SQLERRM);
    RAISE WARNING 'Cost center auto allocation skipped voucher entry %: %', NEW.id, SQLERRM;
  END;
  RETURN NULL;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_auto_after_voucher_finalize()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  item RECORD;
BEGIN
  IF OLD.optional IS DISTINCT FROM TRUE OR NEW.optional IS DISTINCT FROM FALSE
    OR NEW.deleted_at IS NOT NULL THEN RETURN NULL; END IF;
  FOR item IN SELECT id FROM voucher_entries WHERE voucher_id=NEW.id AND company_id=NEW.company_id
  LOOP
    BEGIN
      PERFORM cost_center_auto_apply_voucher_entry(item.id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM cost_center_auto_record_failure(NEW.company_id,'VOUCHER_ENTRY',item.id,SQLERRM);
      RAISE WARNING 'Cost center auto tagging skipped finalized voucher %, entry %: %',
        NEW.id,item.id,SQLERRM;
    END;
  END LOOP;
  RETURN NULL;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_auto_apply_factory_daybook(p_entry_id integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  src RECORD;
  rule_rec RECORD;
  remaining_native NUMERIC(20,6);
  remaining_base NUMERIC(20,6);
  next_native NUMERIC(20,6);
  next_base NUMERIC(20,6);
BEGIN
  SELECT * INTO src FROM factory_daybook_entries
  WHERE id=p_entry_id
    AND tx_type IN ('EXPENSE','OPERATING_EXPENSE','FACTORY_EXPENSE')
    -- An independent event must have no accounting/document reference.
    -- Referenced expenses can share a voucher even when the reference table
    -- isn't literally named "vouchers"; never tag both representations.
    AND nullif(btrim(coalesce(reference_table,'')),'') IS NULL
    AND reference_id IS NULL
    AND amount_currency>0 AND amount_usd>=0;
  IF NOT FOUND THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM cost_center_allocations a WHERE a.factory_daybook_entry_id=p_entry_id)
    OR EXISTS (SELECT 1 FROM cost_center_source_overrides o WHERE o.factory_daybook_entry_id=p_entry_id)
    THEN RETURN; END IF;
  PERFORM pg_advisory_xact_lock(721031,src.company_id);
  remaining_native:=round(abs(src.amount_currency),6);
  remaining_base:=round(abs(src.amount_usd),6);
  FOR rule_rec IN
    SELECT r.* FROM cost_center_auto_rules r
    JOIN cost_centers c ON c.company_id=r.company_id AND c.id=r.cost_center_id AND c.active
    WHERE r.company_id=src.company_id AND r.source_kind='FACTORY_DAYBOOK'
      AND r.factory_tx_type=src.tx_type AND r.active ORDER BY r.id
  LOOP
    next_native:=least(remaining_native,round(src.amount_currency*rule_rec.allocation_percent/100,6));
    next_base:=least(remaining_base,round(src.amount_usd*rule_rec.allocation_percent/100,6));
    IF next_native>0 THEN
      INSERT INTO cost_center_allocations(company_id,cost_center_id,factory_daybook_entry_id,
        amount_native,currency,amount_base,base_currency,historical_rate,
        rate_convention,cost_treatment,allocation_origin,auto_rule_id,created_by,updated_by)
      VALUES (src.company_id,rule_rec.cost_center_id,p_entry_id,next_native,src.currency_code,
        next_base,'USD',src.fx_rate_to_usd,'BASE_PER_TRANSACTION','EXPENSE',
        'AUTO',rule_rec.id,'system:auto','system:auto');
      remaining_native:=remaining_native-next_native;
      remaining_base:=remaining_base-next_base;
    END IF;
  END LOOP;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_auto_apply_voucher_entry(p_entry_id integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  src RECORD;
  rule_rec RECORD;
  remaining_native NUMERIC(20,6);
  remaining_base NUMERIC(20,6);
  next_native NUMERIC(20,6);
  next_base NUMERIC(20,6);
  specificity INTEGER;
BEGIN
  SELECT ve.id,ve.company_id,ve.ledger_account_id,la.account_type,
    v.currency AS voucher_currency,v.source_module,v.optional,v.deleted_at,
    v.voucher_number,
    coalesce(ve.transaction_currency,v.currency,'USD') AS native_currency,
    coalesce(ve.transaction_debit_amount,ve.debit_amount,0) AS native_debit,
    coalesce(ve.transaction_credit_amount,ve.credit_amount,0) AS native_credit,
    coalesce(ve.base_debit_amount,ve.debit_amount,0) AS base_debit,
    coalesce(ve.base_credit_amount,ve.credit_amount,0) AS base_credit,
    ve.debit_amount,ve.credit_amount,
    ve.historical_exchange_rate,ve.rate_convention
  INTO src
  FROM voucher_entries ve
  JOIN vouchers v ON v.id=ve.voucher_id AND v.company_id=ve.company_id
  LEFT JOIN ledger_accounts la ON la.id=ve.ledger_account_id AND la.company_id=ve.company_id
  WHERE ve.id=p_entry_id AND v.deleted_at IS NULL
    AND upper(coalesce(v.source_module,'')) NOT LIKE 'INTERCOMPANY%'
    AND NOT cost_center_voucher_in_reversal_pair(v.id);
  IF NOT FOUND OR src.optional OR src.debit_amount<=0 OR src.credit_amount<>0
      OR src.native_debit<=0 OR src.native_credit<>0
      OR src.base_debit<=0 OR src.base_credit<>0
      OR upper(btrim(coalesce(src.account_type,''))) NOT IN
         ('EXPENSE','DIRECT EXPENSE','INDIRECT EXPENSE')
      OR src.voucher_number LIKE 'GC-%' OR src.voucher_number LIKE 'MIG-%'
      OR src.source_module='SP_MIGRATION_READONLY' THEN RETURN; END IF;

  -- Do not override any manual or previous automatic split; also remember
  -- deliberate CLEAR ALL operations in cost_center_source_overrides.
  IF EXISTS (SELECT 1 FROM cost_center_allocations a WHERE a.voucher_entry_id=p_entry_id)
    OR EXISTS (SELECT 1 FROM cost_center_source_overrides o WHERE o.voucher_entry_id=p_entry_id) THEN
    RETURN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM cost_center_auto_rules r WHERE r.company_id=src.company_id
    AND r.source_kind='VOUCHER_ENTRY' AND r.ledger_account_id=src.ledger_account_id
    AND r.active) THEN RETURN; END IF;

  SELECT CASE WHEN EXISTS (
    SELECT 1 FROM cost_center_auto_rules r JOIN cost_centers c ON c.company_id=r.company_id
       AND c.id=r.cost_center_id AND c.active
    WHERE r.company_id=src.company_id AND r.source_kind='VOUCHER_ENTRY'
      AND r.ledger_account_id=src.ledger_account_id
      AND r.source_module=src.source_module AND r.active
  ) THEN 1 ELSE 0 END INTO specificity;

  PERFORM pg_advisory_xact_lock(721031,src.company_id);
  remaining_native := round(src.native_debit,6);
  remaining_base := round(src.base_debit,6);
  FOR rule_rec IN
    SELECT r.* FROM cost_center_auto_rules r
    JOIN cost_centers c ON c.company_id=r.company_id AND c.id=r.cost_center_id AND c.active
    WHERE r.company_id=src.company_id AND r.source_kind='VOUCHER_ENTRY'
      AND r.ledger_account_id=src.ledger_account_id AND r.active
      AND ((specificity=1 AND r.source_module=src.source_module)
        OR (specificity=0 AND r.source_module IS NULL))
    ORDER BY r.id
  LOOP
    next_native := least(remaining_native,
      round(src.native_debit * rule_rec.allocation_percent / 100,6));
    next_base := least(remaining_base,
      round(src.base_debit * rule_rec.allocation_percent / 100,6));
    IF next_native > 0 THEN
      INSERT INTO cost_center_allocations(company_id,cost_center_id,voucher_entry_id,
        amount_native,currency,amount_base,base_currency,historical_rate,
        rate_convention,cost_treatment,allocation_origin,auto_rule_id,created_by,updated_by)
      VALUES (src.company_id,rule_rec.cost_center_id,p_entry_id,next_native,src.native_currency,
        next_base,'USD',src.historical_exchange_rate,src.rate_convention,'EXPENSE','AUTO',
        rule_rec.id,'system:auto','system:auto');
      remaining_native := remaining_native - next_native;
      remaining_base := remaining_base - next_base;
    END IF;
  END LOOP;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_auto_rules_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  account_kind TEXT;
  account_company INTEGER;
  percent_sum NUMERIC;
BEGIN
  PERFORM pg_advisory_xact_lock(721032, NEW.company_id);
  IF TG_OP='UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN
    RAISE EXCEPTION 'Cannot move auto allocation rules across companies';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM cost_centers c
        WHERE c.company_id=NEW.company_id AND c.id=NEW.cost_center_id AND c.active=true)
      AND NEW.active THEN
    RAISE EXCEPTION 'Auto rule requires an active cost center';
  END IF;
  IF NEW.source_kind='VOUCHER_ENTRY' THEN
    SELECT company_id,upper(btrim(account_type)) INTO account_company,account_kind
      FROM ledger_accounts WHERE id=NEW.ledger_account_id;
    IF account_company IS DISTINCT FROM NEW.company_id
      OR account_kind NOT IN ('EXPENSE','DIRECT EXPENSE','INDIRECT EXPENSE') THEN
      RAISE EXCEPTION 'Automatic voucher rules require an eligible expense account in the same company';
    END IF;
    IF NEW.source_module IS NOT NULL AND length(btrim(NEW.source_module))=0 THEN
      RAISE EXCEPTION 'Source module must not be blank';
    END IF;
  END IF;
  IF NEW.active THEN
    SELECT coalesce(sum(allocation_percent),0) INTO percent_sum
      FROM cost_center_auto_rules r
      WHERE r.company_id=NEW.company_id AND r.source_kind=NEW.source_kind
        AND r.active AND r.id IS DISTINCT FROM NEW.id
        AND r.ledger_account_id IS NOT DISTINCT FROM NEW.ledger_account_id
        AND r.source_module IS NOT DISTINCT FROM NEW.source_module
        AND r.factory_tx_type IS NOT DISTINCT FROM NEW.factory_tx_type;
    IF percent_sum + NEW.allocation_percent > 100 THEN
      RAISE EXCEPTION 'Automatic cost center split exceeds 100 percent for this source';
    END IF;
  END IF;
  RETURN NEW;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_clear_stale_source(p_company_id integer, p_source_kind character varying, p_source_id integer, p_cause text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  cleared INTEGER;
  manual_cleared INTEGER;
  remaining INTEGER;
BEGIN
  IF p_source_kind = 'VOUCHER_ENTRY' THEN
    SELECT count(*), count(*) FILTER (WHERE allocation_origin = 'MANUAL')
      INTO cleared, manual_cleared
      FROM cost_center_allocations WHERE voucher_entry_id = p_source_id;
    DELETE FROM cost_center_allocations WHERE voucher_entry_id = p_source_id;
    PERFORM cost_center_auto_apply_voucher_entry(p_source_id);
    SELECT count(*) INTO remaining FROM cost_center_allocations WHERE voucher_entry_id = p_source_id;
  ELSE
    SELECT count(*), count(*) FILTER (WHERE allocation_origin = 'MANUAL')
      INTO cleared, manual_cleared
      FROM cost_center_allocations WHERE factory_daybook_entry_id = p_source_id;
    DELETE FROM cost_center_allocations WHERE factory_daybook_entry_id = p_source_id;
    PERFORM cost_center_auto_apply_factory_daybook(p_source_id);
    SELECT count(*) INTO remaining FROM cost_center_allocations WHERE factory_daybook_entry_id = p_source_id;
  END IF;
  IF manual_cleared > 0 OR (cleared > 0 AND remaining = 0) THEN
    PERFORM cost_center_auto_record_failure(p_company_id, p_source_kind, p_source_id,
      format('%s; %s cost center split(s) cleared for review (%s manual). Accounting was not changed.',
        p_cause, cleared, manual_cleared));
  END IF;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_factory_daybook_change_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM cost_center_allocations WHERE factory_daybook_entry_id = OLD.id) THEN
    RETURN NULL;
  END IF;
  BEGIN
    IF NEW.company_id IS DISTINCT FROM OLD.company_id OR
       NEW.reference_table IS DISTINCT FROM OLD.reference_table OR
       NEW.reference_id IS DISTINCT FROM OLD.reference_id OR
       NEW.tx_type IS DISTINCT FROM OLD.tx_type OR
       NEW.currency_code IS DISTINCT FROM OLD.currency_code OR
       NEW.amount_currency IS DISTINCT FROM OLD.amount_currency OR
       NEW.amount_usd IS DISTINCT FROM OLD.amount_usd THEN
      PERFORM cost_center_clear_stale_source(OLD.company_id, 'FACTORY_DAYBOOK', OLD.id,
        'Factory daybook amount, currency, type or reference changed after allocation');
    ELSIF NEW.fx_rate_to_usd IS DISTINCT FROM OLD.fx_rate_to_usd THEN
      UPDATE cost_center_allocations
        SET historical_rate = NEW.fx_rate_to_usd,
            updated_by = 'system:source-change', updated_at = now()
        WHERE factory_daybook_entry_id = OLD.id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM cost_center_auto_record_failure(OLD.company_id, 'FACTORY_DAYBOOK', OLD.id,
      'Cost center follow-up after a Factory daybook change failed: ' || SQLERRM);
    RAISE WARNING 'Cost center follow-up skipped factory daybook entry %: %', OLD.id, SQLERRM;
  END;
  RETURN NULL;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_monthly_budgets_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='UPDATE' AND (
    NEW.company_id IS DISTINCT FROM OLD.company_id OR
    NEW.cost_center_id IS DISTINCT FROM OLD.cost_center_id
  ) THEN
    RAISE EXCEPTION 'Budget company and cost center are immutable';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM cost_centers c WHERE c.company_id=NEW.company_id
      AND c.id=NEW.cost_center_id AND c.active
  ) THEN
    RAISE EXCEPTION 'New or updated budgets require an active cost center';
  END IF;
  RETURN NEW;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_source_delete_notice()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  manual_count INTEGER;
  kind VARCHAR := CASE WHEN TG_TABLE_NAME = 'voucher_entries' THEN 'VOUCHER_ENTRY' ELSE 'FACTORY_DAYBOOK' END;
BEGIN
  BEGIN
    IF kind = 'VOUCHER_ENTRY' THEN
      SELECT count(*) INTO manual_count FROM cost_center_allocations
        WHERE voucher_entry_id = OLD.id AND allocation_origin = 'MANUAL';
    ELSE
      SELECT count(*) INTO manual_count FROM cost_center_allocations
        WHERE factory_daybook_entry_id = OLD.id AND allocation_origin = 'MANUAL';
    END IF;
    IF manual_count > 0 THEN
      PERFORM cost_center_auto_record_failure(OLD.company_id, kind, OLD.id,
        format('Source deleted; %s manual cost center split(s) were removed with it. Re-assign the replacement entry if needed.',
          manual_count));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Cost center delete notice skipped source %: %', OLD.id, SQLERRM;
  END;
  RETURN OLD;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_source_override_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  source_company INTEGER;
BEGIN
  IF TG_OP='UPDATE' AND (
    NEW.company_id IS DISTINCT FROM OLD.company_id
    OR NEW.voucher_entry_id IS DISTINCT FROM OLD.voucher_entry_id
    OR NEW.factory_daybook_entry_id IS DISTINCT FROM OLD.factory_daybook_entry_id
  ) THEN RAISE EXCEPTION 'Cannot change the company or source of a manual override'; END IF;
  IF NEW.voucher_entry_id IS NOT NULL AND NEW.factory_daybook_entry_id IS NULL THEN
    SELECT company_id INTO source_company FROM voucher_entries WHERE id=NEW.voucher_entry_id;
  ELSIF NEW.factory_daybook_entry_id IS NOT NULL AND NEW.voucher_entry_id IS NULL THEN
    SELECT company_id INTO source_company FROM factory_daybook_entries
    WHERE id=NEW.factory_daybook_entry_id;
  ELSE
    RAISE EXCEPTION 'Manual override must reference exactly one financial source';
  END IF;
  IF source_company IS DISTINCT FROM NEW.company_id THEN
    RAISE EXCEPTION 'Manual override must refer to a source in the same company';
  END IF;
  RETURN NEW;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_voucher_change_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  item RECORD;
BEGIN
  IF NEW.company_id IS NOT DISTINCT FROM OLD.company_id
     AND NEW.currency IS NOT DISTINCT FROM OLD.currency THEN
    RETURN NULL;
  END IF;
  FOR item IN
    SELECT DISTINCT ve.id FROM voucher_entries ve
    JOIN cost_center_allocations a ON a.voucher_entry_id = ve.id
    WHERE ve.voucher_id = OLD.id
      AND (NEW.company_id IS DISTINCT FROM OLD.company_id OR ve.transaction_currency IS NULL)
  LOOP
    BEGIN
      PERFORM cost_center_clear_stale_source(OLD.company_id, 'VOUCHER_ENTRY', item.id,
        'Voucher company or currency changed after allocation');
    EXCEPTION WHEN OTHERS THEN
      PERFORM cost_center_auto_record_failure(OLD.company_id, 'VOUCHER_ENTRY', item.id,
        'Cost center follow-up after a voucher change failed: ' || SQLERRM);
      RAISE WARNING 'Cost center follow-up skipped voucher %, entry %: %', OLD.id, item.id, SQLERRM;
    END;
  END LOOP;
  RETURN NULL;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_center_voucher_entry_change_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  monetary_changed BOOLEAN;
  new_type TEXT;
  new_code TEXT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM cost_center_allocations WHERE voucher_entry_id = OLD.id) THEN
    RETURN NULL;
  END IF;
  BEGIN
    monetary_changed :=
      NEW.company_id IS DISTINCT FROM OLD.company_id OR
      NEW.voucher_id IS DISTINCT FROM OLD.voucher_id OR
      NEW.debit_amount IS DISTINCT FROM OLD.debit_amount OR
      NEW.credit_amount IS DISTINCT FROM OLD.credit_amount OR
      NEW.transaction_currency IS DISTINCT FROM OLD.transaction_currency OR
      NEW.transaction_debit_amount IS DISTINCT FROM OLD.transaction_debit_amount OR
      NEW.transaction_credit_amount IS DISTINCT FROM OLD.transaction_credit_amount OR
      NEW.base_debit_amount IS DISTINCT FROM OLD.base_debit_amount OR
      NEW.base_credit_amount IS DISTINCT FROM OLD.base_credit_amount;
    IF NOT monetary_changed THEN
      IF NEW.ledger_account_id IS DISTINCT FROM OLD.ledger_account_id THEN
        SELECT upper(btrim(account_type)), code INTO new_type, new_code
          FROM ledger_accounts WHERE id = NEW.ledger_account_id AND company_id = NEW.company_id;
        IF EXISTS (
          SELECT 1 FROM cost_center_allocations a
          WHERE a.voucher_entry_id = OLD.id AND NOT (
            (a.cost_treatment = 'EXPENSE'
              AND coalesce(new_type, '') IN ('EXPENSE', 'DIRECT EXPENSE', 'INDIRECT EXPENSE'))
            OR (a.cost_treatment = 'INVENTORY_COST' AND new_type = 'ASSET'
              AND new_code IN ('FACTORY_RAW_MATERIAL_STOCK', 'FACTORY_WIP', 'FACTORY_FINISHED_GOODS'))
          )
        ) THEN
          PERFORM cost_center_clear_stale_source(OLD.company_id, 'VOUCHER_ENTRY', OLD.id,
            'Voucher entry moved to an ineligible ledger account');
          RETURN NULL;
        END IF;
      END IF;
      IF NEW.historical_exchange_rate IS DISTINCT FROM OLD.historical_exchange_rate
         OR NEW.rate_convention IS DISTINCT FROM OLD.rate_convention THEN
        UPDATE cost_center_allocations
          SET historical_rate = NEW.historical_exchange_rate,
              rate_convention = NEW.rate_convention,
              updated_by = 'system:source-change', updated_at = now()
          WHERE voucher_entry_id = OLD.id;
      END IF;
      RETURN NULL;
    END IF;
    PERFORM cost_center_clear_stale_source(OLD.company_id, 'VOUCHER_ENTRY', OLD.id,
      'Voucher entry amount, currency or source changed after allocation');
  EXCEPTION WHEN OTHERS THEN
    PERFORM cost_center_auto_record_failure(OLD.company_id, 'VOUCHER_ENTRY', OLD.id,
      'Cost center follow-up after a voucher entry change failed: ' || SQLERRM);
    RAISE WARNING 'Cost center follow-up skipped voucher entry %: %', OLD.id, SQLERRM;
  END;
  RETURN NULL;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.cost_centers_guard_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(721030, NEW.company_id);

  IF TG_OP = 'UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN
    RAISE EXCEPTION 'Cost centers cannot be moved between companies';
  END IF;

  IF NEW.parent_id IS NOT NULL THEN
    IF EXISTS (
      WITH RECURSIVE ancestors(id, parent_id) AS (
        SELECT id, parent_id FROM cost_centers
        WHERE company_id = NEW.company_id AND id = NEW.parent_id
        UNION
        SELECT p.id, p.parent_id
        FROM cost_centers p
        INNER JOIN ancestors a ON p.id = a.parent_id
        WHERE p.company_id = NEW.company_id
      )
      SELECT 1 FROM ancestors WHERE id = NEW.id
    ) THEN
      RAISE EXCEPTION 'Cost center hierarchy cannot contain a cycle';
    END IF;
  END IF;

  RETURN NEW;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.enforce_tenant_control_child_company()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  referenced_company_id integer;
BEGIN
  IF TG_TABLE_NAME = 'user_company_roles' THEN
    IF NEW.assigned_location_id IS NOT NULL THEN
      SELECT company_id INTO referenced_company_id
      FROM locations
      WHERE id = NEW.assigned_location_id;

      IF referenced_company_id IS NULL THEN
        RAISE EXCEPTION USING
          ERRCODE = '23503',
          MESSAGE = 'assigned location does not exist';
      END IF;
      IF referenced_company_id <> NEW.company_id THEN
        RAISE EXCEPTION USING
          ERRCODE = '23514',
          MESSAGE = 'assigned location belongs to another company';
      END IF;
    END IF;

    IF NEW.cash_account_id IS NOT NULL THEN
      SELECT company_id INTO referenced_company_id
      FROM ledger_accounts
      WHERE id = NEW.cash_account_id;

      IF referenced_company_id IS NULL THEN
        RAISE EXCEPTION USING
          ERRCODE = '23503',
          MESSAGE = 'cash account does not exist';
      END IF;
      IF referenced_company_id <> NEW.company_id THEN
        RAISE EXCEPTION USING
          ERRCODE = '23514',
          MESSAGE = 'cash account belongs to another company';
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'user_locations' THEN
    SELECT company_id INTO referenced_company_id
    FROM locations
    WHERE id = NEW.location_id;

    IF referenced_company_id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '23503',
        MESSAGE = 'assigned location does not exist';
    END IF;
    IF referenced_company_id <> NEW.company_id THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'user location belongs to another company';
    END IF;

  ELSIF TG_TABLE_NAME = 'user_location_cash_accounts' THEN
    SELECT company_id INTO referenced_company_id
    FROM locations
    WHERE id = NEW.location_id;

    IF referenced_company_id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '23503',
        MESSAGE = 'POS location does not exist';
    END IF;
    IF referenced_company_id <> NEW.company_id THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'POS location belongs to another company';
    END IF;

    SELECT company_id INTO referenced_company_id
    FROM ledger_accounts
    WHERE id = NEW.cash_account_id;

    IF referenced_company_id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '23503',
        MESSAGE = 'POS cash account does not exist';
    END IF;
    IF referenced_company_id <> NEW.company_id THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'POS cash account belongs to another company';
    END IF;
  END IF;

  RETURN NEW;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.ensure_user_credential_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  INSERT INTO user_credential_versions(user_id, credential_version, updated_at)
  VALUES (NEW.id, 0, now())
  ON CONFLICT (user_id) DO NOTHING;
  RETURN NEW;
END;
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_assert_accounting_date_open(p_company_id integer, p_date date)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
   DECLARE
     locked_through date;
   BEGIN
     IF p_company_id IS NULL OR p_date IS NULL OR erp_closed_period_guard_bypassed() THEN
       RETURN;
     END IF;

     PERFORM pg_advisory_xact_lock_shared(74122, p_company_id);

     SELECT max(period_end_date) INTO locked_through
       FROM fiscal_period_closures
      WHERE company_id = p_company_id
        AND status = 'CLOSED';

     IF locked_through IS NOT NULL AND p_date <= locked_through THEN
       RAISE EXCEPTION USING
         ERRCODE = 'EPL01',
         MESSAGE = format(
           'ACCOUNTING_PERIOD_CLOSED: the books are closed through %s, so an entry dated %s cannot be created, changed or deleted',
           locked_through,
           p_date
         ),
         HINT = 'Post a correcting entry dated after the closed period.';
     END IF;
   END
   $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_assert_opening_balance_open(p_company_id integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
   DECLARE
     locked_through date;
   BEGIN
     IF p_company_id IS NULL OR erp_closed_period_guard_bypassed() THEN RETURN; END IF;
     PERFORM pg_advisory_xact_lock_shared(74122, p_company_id);
     SELECT max(period_end_date) INTO locked_through
       FROM fiscal_period_closures WHERE company_id = p_company_id AND status = 'CLOSED';
     IF locked_through IS NOT NULL THEN
       RAISE EXCEPTION USING
         ERRCODE = 'EPL01',
         MESSAGE = format(
           'ACCOUNTING_PERIOD_CLOSED: the books are closed through %s, so an opening balance cannot be created, changed or deleted',
           locked_through
         ),
         HINT = 'Post an adjusting journal dated after the closed period, or reopen the period.';
     END IF;
   END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_assert_voucher_open(p_voucher_id integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
   DECLARE
     parent record;
   BEGIN
     IF p_voucher_id IS NULL OR erp_closed_period_guard_bypassed() THEN
       RETURN;
     END IF;
     SELECT company_id, voucher_date, effective_date INTO parent FROM vouchers WHERE id = p_voucher_id;
     -- No visible parent: an insert fails its foreign key anyway, and a cascade
     -- from a voucher delete was already checked by the vouchers trigger.
     IF NOT FOUND THEN
       RETURN;
     END IF;
     PERFORM erp_assert_accounting_date_open(parent.company_id, parent.voucher_date);
     PERFORM erp_assert_accounting_date_open(parent.company_id, parent.effective_date);
   END
   $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_audit_log_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     v_prev text;
   BEGIN
     NEW.request_id := COALESCE(NEW.request_id, NULLIF(btrim(current_setting('app.request_id', true)), ''));
     NEW.ip := COALESCE(NEW.ip, NULLIF(btrim(current_setting('app.request_ip', true)), ''));
     NEW.session_id := COALESCE(NEW.session_id, NULLIF(btrim(current_setting('app.session_hash', true)), ''));
     NEW.reason := COALESCE(NEW.reason, NULLIF(btrim(current_setting('app.audit_reason', true)), ''));
     NEW.prev_hash := NULL;
     IF erp_audit_log_is_financial(NEW.table_name) THEN
       SELECT a.row_hash INTO v_prev FROM audit_log a
        WHERE a.prev_hash IS NOT NULL AND a.id < NEW.id
        ORDER BY a.id DESC LIMIT 1;
       NEW.prev_hash := COALESCE(v_prev, 'genesis');
     END IF;
     NEW.row_hash := erp_audit_log_row_hash(NEW);
     RETURN NEW;
   END
   $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_authorized_company_ids()
 RETURNS integer[]
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  raw_company_ids text;
  parsed_company_ids integer[];
BEGIN
  raw_company_ids := current_setting('app.authorized_company_ids', true);
  IF raw_company_ids IS NULL OR btrim(raw_company_ids) = '' THEN
    RETURN ARRAY[]::integer[];
  END IF;

  BEGIN
    parsed_company_ids := string_to_array(raw_company_ids, ',')::integer[];
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'app.authorized_company_ids must be a comma-separated list of positive integers';
  END;

  IF EXISTS (SELECT 1 FROM unnest(parsed_company_ids) AS company_id WHERE company_id <= 0) THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'app.authorized_company_ids must contain only positive integers';
  END IF;

  RETURN parsed_company_ids;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_bank_account_delete_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     balance numeric;
   BEGIN
     IF erp_ledger_integrity_bypassed() OR NEW.deleted_at IS NULL OR OLD.deleted_at IS NOT NULL THEN
       RETURN NEW;
     END IF;
     SELECT (CASE WHEN OLD.opening_balance_side = 'Cr' THEN -1 ELSE 1 END) * COALESCE(OLD.opening_balance, 0)
            + COALESCE(SUM(ve.debit_amount - ve.credit_amount), 0)
       INTO balance
       FROM voucher_entries ve JOIN vouchers v ON v.id = ve.voucher_id
      WHERE ve.bank_account_id = OLD.id AND ve.ledger_account_id IS NULL
        AND v.deleted_at IS NULL AND v.optional = false;
     IF balance <> 0 THEN
       RAISE EXCEPTION USING ERRCODE = '23514',
         MESSAGE = format('BANK_ACCOUNT_HAS_BALANCE: bank account %s has a balance of %s and cannot be deleted', OLD.id, balance),
         HINT = 'Move its balance to another account with a journal entry first, or deactivate it instead.';
     END IF;
     RETURN NEW;
   END
   $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_company_scope_maintenance_enabled()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  raw_maintenance text;
BEGIN
  raw_maintenance := current_setting('app.company_scope_maintenance', true);
  IF raw_maintenance IS NULL OR btrim(raw_maintenance) = '' OR lower(btrim(raw_maintenance)) = 'off' THEN
    RETURN false;
  END IF;
  IF lower(btrim(raw_maintenance)) = 'on' THEN
    RETURN true;
  END IF;

  RAISE EXCEPTION USING
    ERRCODE = '22023',
    MESSAGE = 'app.company_scope_maintenance must be on or off';
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_company_scope_matches(row_company_id integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  current_company_id integer;
BEGIN
  IF erp_company_scope_maintenance_enabled() THEN
    RETURN true;
  END IF;

  current_company_id := erp_current_company_id();
  RETURN row_company_id = current_company_id OR row_company_id = ANY(erp_authorized_company_ids());
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_current_company_id()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  raw_company_id text;
  parsed_company_id integer;
BEGIN
  raw_company_id := current_setting('app.current_company_id', true);
  IF raw_company_id IS NULL OR btrim(raw_company_id) = '' THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'app.current_company_id is required for tenant data access';
  END IF;

  -- Deliberately allow PostgreSQL to raise on malformed or overflowing input.
  -- Returning NULL would make an invalid tenant assertion indistinguishable
  -- from an omitted tenant identity.
  parsed_company_id := raw_company_id::integer;
  IF parsed_company_id <= 0 THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'app.current_company_id must be a positive integer';
  END IF;
  RETURN parsed_company_id;
END
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_factory_row_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     v_actor text := COALESCE(NULLIF(btrim(current_setting('app.current_actor', true)), ''), 'unknown');
     v_noise text[] := TG_ARGV;
     v_previous_maintenance text := current_setting('app.company_scope_maintenance',true);
   BEGIN
     -- Scope elevation is limited to internal audit insertion and immediately restored.
     PERFORM set_config('app.company_scope_maintenance','on',true);
     IF TG_OP = 'INSERT' THEN
       INSERT INTO factory_row_history (table_name, record_id, company_id, op, recorded_at, actor, new_values)
       SELECT TG_TABLE_NAME, (img->>'id')::bigint, erp_factory_row_history_company_id(TG_TABLE_NAME,img), 'I', (clock_timestamp() AT TIME ZONE 'UTC'), v_actor, img
         FROM (SELECT to_jsonb(n) AS img FROM history_new n) AS rows;
     ELSIF TG_OP = 'UPDATE' THEN
       INSERT INTO factory_row_history (table_name, record_id, company_id, op, recorded_at, actor, old_values, new_values)
       SELECT TG_TABLE_NAME, (rows.after->>'id')::bigint, erp_factory_row_history_company_id(TG_TABLE_NAME,rows.after), 'U', (clock_timestamp() AT TIME ZONE 'UTC'), v_actor,
              diff.old_values, diff.new_values
         FROM (SELECT to_jsonb(o) AS before, to_jsonb(n) AS after
                 FROM history_old o JOIN history_new n ON n.id = o.id) AS rows
        CROSS JOIN LATERAL (
          SELECT jsonb_object_agg(e.key, e.value) AS old_values,
                 jsonb_object_agg(e.key, rows.after -> e.key) AS new_values,
                 bool_or(e.key <> 'updated_at'
                         AND NOT EXISTS (SELECT 1 FROM unnest(v_noise) AS p WHERE starts_with(e.key, p))) AS material
            FROM jsonb_each(rows.before) AS e
           WHERE e.value IS DISTINCT FROM rows.after -> e.key
        ) AS diff
        WHERE diff.material;
     ELSE
       INSERT INTO factory_row_history (table_name, record_id, company_id, op, recorded_at, actor, old_values)
       SELECT TG_TABLE_NAME, (img->>'id')::bigint, erp_factory_row_history_company_id(TG_TABLE_NAME,img), 'D', (clock_timestamp() AT TIME ZONE 'UTC'), v_actor, img
         FROM (SELECT to_jsonb(o) AS img FROM history_old o) AS rows;
     END IF;
     PERFORM set_config('app.company_scope_maintenance',COALESCE(NULLIF(v_previous_maintenance,''),'off'),true);
     RETURN NULL;
   END
   $function$
","publicExecute":true,"comment":"2026-10-factory-row-history-v6-audit-write-scope"}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_factory_row_history_company_id(p_table text, p_row jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
   DECLARE v_company integer;
   BEGIN
     IF p_row ? 'company_id' THEN RETURN (p_row->>'company_id')::integer; END IF;
     IF p_table IN ('customer_order_bales','customer_order_charges') THEN
       SELECT company_id INTO v_company FROM customer_orders WHERE id = (p_row->>'order_id')::integer;
     ELSIF p_table = 'factory_mix_batch_sources' THEN
       SELECT company_id INTO v_company FROM factory_mix_batches WHERE id = (p_row->>'mix_batch_id')::integer;
     END IF;
     IF v_company IS NULL THEN
       SELECT company_id INTO v_company FROM factory_row_history
        WHERE table_name = p_table AND record_id = (p_row->>'id')::bigint
          AND company_id IS NOT NULL ORDER BY id DESC LIMIT 1;
     END IF;
     RETURN v_company;
   END
   $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_ledger_account_tree_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     parent record;
     reason text;
     child_check boolean;
   BEGIN
     IF erp_ledger_integrity_bypassed() THEN RETURN NEW; END IF;
     child_check := NEW.parent_id IS NOT NULL AND (
       TG_OP = 'INSERT'
       OR NEW.parent_id IS DISTINCT FROM OLD.parent_id
       OR NEW.company_id IS DISTINCT FROM OLD.company_id
       OR erp_ledger_account_class(NEW.account_type, NEW.sub_type)
          IS DISTINCT FROM erp_ledger_account_class(OLD.account_type, OLD.sub_type)
       OR (NEW.deleted_at IS NULL AND OLD.deleted_at IS NOT NULL));
     IF child_check THEN
       IF NEW.parent_id = NEW.id THEN
         reason := 'an account cannot be its own parent';
       ELSE
         SELECT id, company_id, deleted_at, account_type, sub_type INTO parent
           FROM ledger_accounts WHERE id = NEW.parent_id;
         IF NOT FOUND OR parent.company_id IS DISTINCT FROM NEW.company_id THEN
           reason := 'the parent is not an account of this company';
         ELSIF parent.deleted_at IS NOT NULL THEN
           reason := 'the parent account is deleted';
         ELSIF erp_ledger_account_class(parent.account_type, parent.sub_type)
               IS DISTINCT FROM erp_ledger_account_class(NEW.account_type, NEW.sub_type) THEN
           reason := format('the parent is %s and the account is %s',
             erp_ledger_account_class(parent.account_type, parent.sub_type),
             erp_ledger_account_class(NEW.account_type, NEW.sub_type));
         ELSIF TG_OP = 'UPDATE' AND EXISTS (
           WITH RECURSIVE ancestors(id, parent_id, depth) AS (
             SELECT la.id, la.parent_id, 1 FROM ledger_accounts la WHERE la.id = NEW.parent_id
             UNION ALL
             SELECT la.id, la.parent_id, a.depth + 1
               FROM ledger_accounts la JOIN ancestors a ON la.id = a.parent_id
              WHERE a.depth < 1000)
           SELECT 1 FROM ancestors WHERE id = NEW.id) THEN
           reason := 'the parent is the account itself or one of its sub-accounts';
         END IF;
       END IF;
     END IF;
     IF reason IS NULL AND TG_OP = 'UPDATE'
        AND (NEW.company_id IS DISTINCT FROM OLD.company_id
             OR erp_ledger_account_class(NEW.account_type, NEW.sub_type)
                IS DISTINCT FROM erp_ledger_account_class(OLD.account_type, OLD.sub_type)
             OR (NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL))
        AND EXISTS (SELECT 1 FROM ledger_accounts c WHERE c.parent_id = OLD.id AND c.deleted_at IS NULL) THEN
       reason := 'the account has sub-accounts: move them first';
     END IF;
     IF reason IS NOT NULL THEN
       RAISE EXCEPTION USING ERRCODE = '23514',
         MESSAGE = format('LEDGER_ACCOUNT_PARENT_INVALID: account %s: %s', COALESCE(NEW.code, NEW.name), reason);
     END IF;
     RETURN NEW;
   END
   $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_opening_balance_lock_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     new_row jsonb := to_jsonb(NEW);
     old_row jsonb;
     new_amount numeric := COALESCE((to_jsonb(NEW)->>'opening_balance')::numeric, 0);
     old_amount numeric;
     new_company integer := (to_jsonb(NEW)->>'company_id')::integer;
     old_company integer;
   BEGIN
     IF TG_OP = 'DELETE' THEN
       IF COALESCE((to_jsonb(OLD)->>'opening_balance')::numeric, 0) <> 0 THEN
         PERFORM erp_assert_opening_balance_open((to_jsonb(OLD)->>'company_id')::integer);
       END IF;
       RETURN OLD;
     END IF;
     IF TG_OP = 'INSERT' THEN
       IF new_amount <> 0 THEN PERFORM erp_assert_opening_balance_open(new_company); END IF;
       RETURN NEW;
     END IF;
     old_row := to_jsonb(OLD);
     old_amount := COALESCE((old_row->>'opening_balance')::numeric, 0);
     old_company := (old_row->>'company_id')::integer;
     IF new_amount <> old_amount
        OR ((new_amount <> 0 OR old_amount <> 0)
            AND ((new_row->>'deleted_at') IS NULL) IS DISTINCT FROM ((old_row->>'deleted_at') IS NULL))
        OR (new_amount <> 0 AND COALESCE(new_row->>'opening_balance_side', 'Dr') IS DISTINCT FROM COALESCE(old_row->>'opening_balance_side', 'Dr'))
        OR ((new_amount <> 0 OR old_amount <> 0) AND new_company IS DISTINCT FROM old_company) THEN
       PERFORM erp_assert_opening_balance_open(old_company);
       IF new_company IS DISTINCT FROM old_company THEN
         PERFORM erp_assert_opening_balance_open(new_company);
       END IF;
     END IF;
     RETURN NEW;
   END $function$
","publicExecute":true,"comment":"2026-10-opening-balance-lock-v3"}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_stock_adjustment_vouchers_balance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   BEGIN
     PERFORM erp_voucher_balance_check(OLD.voucher_id);
     IF TG_OP = 'UPDATE' THEN PERFORM erp_voucher_balance_check(NEW.voucher_id); END IF;
     RETURN NULL;
   END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_voucher_balance_check(p_voucher_id integer, p_lines_changed boolean)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
   DECLARE
     v record;
     currencies integer;
     all_in_currency boolean;
     debit_lines integer;
     credit_lines integer;
     base_debit numeric;
     base_credit numeric;
     txn_debit numeric;
     txn_credit numeric;
     base_tolerance numeric := 0;
   BEGIN
     IF p_voucher_id IS NULL OR erp_ledger_integrity_bypassed() THEN RETURN; END IF;
     SELECT vo.id, vo.voucher_number, vo.voucher_type, vo.balance_guard_exempt_history AS history,
            vo.posted_by_engine AS engine,
            COALESCE(co.company_type, '') AS company_type,
            EXISTS (SELECT 1 FROM gl_inventory_cutovers c
                     WHERE c.company_id = vo.company_id AND c.effective_from <= vo.voucher_date) AS perpetual
       INTO v
       FROM vouchers vo JOIN companies co ON co.id = vo.company_id
      WHERE vo.id = p_voucher_id AND vo.deleted_at IS NULL AND COALESCE(vo.optional, false) = false;
     -- D1: a history voucher is checked only when its lines change.
     IF NOT FOUND OR (v.history AND NOT p_lines_changed) THEN RETURN; END IF;

     -- v6: the engine's ROUNDING line (USD, base only) is left out of the
     -- transaction-currency check; it is part of the base sums.
     SELECT COUNT(DISTINCT l.transaction_currency) FILTER (WHERE l.transaction_currency IS NOT NULL AND NOT l.rounding),
            COALESCE(bool_and(l.transaction_currency IS NOT NULL) FILTER (WHERE NOT l.rounding), false),
            COUNT(*) FILTER (WHERE COALESCE(l.debit_amount, 0) <> 0 OR COALESCE(l.transaction_debit_amount, 0) <> 0),
            COUNT(*) FILTER (WHERE COALESCE(l.credit_amount, 0) <> 0 OR COALESCE(l.transaction_credit_amount, 0) <> 0),
            COALESCE(SUM(l.debit_amount), 0), COALESCE(SUM(l.credit_amount), 0),
            COALESCE(SUM(l.transaction_debit_amount) FILTER (WHERE NOT l.rounding), 0),
            COALESCE(SUM(l.transaction_credit_amount) FILTER (WHERE NOT l.rounding), 0)
       INTO currencies, all_in_currency, debit_lines, credit_lines, base_debit, base_credit, txn_debit, txn_credit
       FROM (SELECT ve.*,
                    COALESCE(ve.narration = 'Base currency rounding difference' AND ve.rate_convention = 'IDENTITY'
                             AND EXISTS (SELECT 1 FROM ledger_accounts la
                                          WHERE la.id = ve.ledger_account_id AND la.code = 'ROUNDING'),
                             false) AS rounding
               FROM voucher_entries ve WHERE ve.voucher_id = p_voucher_id) l;

     -- Periodic stock adjustment: one-sided by design when a stock document backs it.
     IF v.voucher_type IN ('Stock Adjustment', 'Production', 'Consumption', 'Mixed')
        AND (NOT v.perpetual OR v.company_type = 'supplier_partner')
        AND (debit_lines = 0 OR credit_lines = 0)
        AND EXISTS (SELECT 1 FROM stock_adjustment_vouchers sav
                      JOIN stock_adjustment_items sai ON sai.adjustment_id = sav.id
                     WHERE sav.voucher_id = p_voucher_id) THEN
       RETURN;
     END IF;

     IF currencies = 1 AND all_in_currency THEN
       -- v6 (phase 22 A, D3, owner decision): a new voucher balances exactly
       -- (the engine adds its ROUNDING line); history keeps the one-cent tolerance.
       IF v.history THEN base_tolerance := 0.01; END IF;
       IF round(txn_debit, 2) <> round(txn_credit, 2) THEN
         RAISE EXCEPTION 'Voucher % does not balance in its transaction currency: debits %, credits %',
           v.voucher_number, round(txn_debit, 2), round(txn_credit, 2)
           USING ERRCODE = '23514';
       END IF;
     END IF;
     IF abs(round(base_debit, 2) - round(base_credit, 2)) > base_tolerance THEN
       RAISE EXCEPTION 'Voucher % does not balance: debits %, credits %',
         v.voucher_number, round(base_debit, 2), round(base_credit, 2)
         USING ERRCODE = '23514';
     END IF;

   END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_voucher_entries_balance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     lines_changed boolean := true;
   BEGIN
     IF TG_OP = 'UPDATE' THEN
       lines_changed :=
         (NEW.voucher_id, NEW.ledger_account_id, NEW.bank_account_id, NEW.fixed_asset_id, NEW.supplier_id,
          NEW.employee_id, NEW.customer_id, NEW.factory_supplier_id, NEW.debit_amount, NEW.credit_amount,
          NEW.transaction_currency, NEW.transaction_debit_amount, NEW.transaction_credit_amount)
         IS DISTINCT FROM
         (OLD.voucher_id, OLD.ledger_account_id, OLD.bank_account_id, OLD.fixed_asset_id, OLD.supplier_id,
          OLD.employee_id, OLD.customer_id, OLD.factory_supplier_id, OLD.debit_amount, OLD.credit_amount,
          OLD.transaction_currency, OLD.transaction_debit_amount, OLD.transaction_credit_amount);
     END IF;
     IF TG_OP IN ('INSERT', 'UPDATE') THEN PERFORM erp_voucher_balance_check(NEW.voucher_id, lines_changed); END IF;
     IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD.voucher_id IS DISTINCT FROM NEW.voucher_id) THEN
       PERFORM erp_voucher_balance_check(OLD.voucher_id, true);
     END IF;
     RETURN NULL;
   END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_voucher_entries_closed_period_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     financial_change boolean := true;
   BEGIN
     IF TG_OP = 'UPDATE' THEN
       financial_change :=
         (NEW.voucher_id, NEW.ledger_account_id, NEW.bank_account_id, NEW.fixed_asset_id, NEW.supplier_id,
          NEW.employee_id, NEW.customer_id, NEW.factory_supplier_id, NEW.debit_amount, NEW.credit_amount,
          NEW.transaction_currency, NEW.transaction_debit_amount, NEW.transaction_credit_amount,
          NEW.base_debit_amount, NEW.base_credit_amount, NEW.historical_exchange_rate, NEW.rate_convention)
         IS DISTINCT FROM
         (OLD.voucher_id, OLD.ledger_account_id, OLD.bank_account_id, OLD.fixed_asset_id, OLD.supplier_id,
          OLD.employee_id, OLD.customer_id, OLD.factory_supplier_id, OLD.debit_amount, OLD.credit_amount,
          OLD.transaction_currency, OLD.transaction_debit_amount, OLD.transaction_credit_amount,
          OLD.base_debit_amount, OLD.base_credit_amount, OLD.historical_exchange_rate, OLD.rate_convention);
     END IF;

     IF NOT financial_change THEN
       RETURN NEW;
     END IF;

     IF TG_OP IN ('UPDATE', 'DELETE') THEN
       PERFORM erp_assert_voucher_open(OLD.voucher_id);
     END IF;
     IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.voucher_id IS DISTINCT FROM OLD.voucher_id) THEN
       PERFORM erp_assert_voucher_open(NEW.voucher_id);
     END IF;

     IF TG_OP = 'DELETE' THEN
       RETURN OLD;
     END IF;
     RETURN NEW;
   END
   $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_voucher_entry_target_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     target_company integer;
     target_deleted timestamp;
     parent_company integer;
     account_targets integer;
     party_targets integer;
   BEGIN
     IF erp_ledger_integrity_bypassed() THEN
       RETURN NEW;
     END IF;
     IF TG_OP = 'UPDATE'
        AND (NEW.company_id, NEW.ledger_account_id, NEW.bank_account_id, NEW.fixed_asset_id, NEW.supplier_id,
             NEW.employee_id, NEW.customer_id, NEW.factory_supplier_id)
            IS NOT DISTINCT FROM
            (OLD.company_id, OLD.ledger_account_id, OLD.bank_account_id, OLD.fixed_asset_id, OLD.supplier_id,
             OLD.employee_id, OLD.customer_id, OLD.factory_supplier_id)
     THEN
       RETURN NEW;
     END IF;

     -- Wave 16 (B): a new line, or a line whose targets change, must have one
     -- owner under the engine's attribution (partyLineRules.ts): exactly one
     -- account (ledger, bank or fixed asset) with at most one party tag
     -- (supplier, employee, factory supplier or customer) — a tag on an
     -- account line belongs to the account — or, with no account, exactly one
     -- party. The one pair of accounts the engine defines is a bank with its
     -- own linked ledger (the line counts on the ledger). A line with no target
     -- (no owner) or with two accounts or two parties is refused. Existing
     -- lines are exempt: an update that leaves the targets alone returned above.
     account_targets := num_nonnulls(NEW.ledger_account_id, NEW.bank_account_id, NEW.fixed_asset_id);
     party_targets := num_nonnulls(NEW.supplier_id, NEW.employee_id, NEW.factory_supplier_id, NEW.customer_id);
     IF account_targets = 2 AND NEW.fixed_asset_id IS NULL
        AND EXISTS (SELECT 1 FROM bank_accounts b
                     WHERE b.id = NEW.bank_account_id AND b.linked_ledger_id = NEW.ledger_account_id) THEN
       account_targets := 1;
     END IF;
     IF NOT ((account_targets = 1 AND party_targets <= 1) OR (account_targets = 0 AND party_targets = 1)) THEN
       RAISE EXCEPTION USING ERRCODE = '23514',
         MESSAGE = format('VOUCHER_LINE_TARGET_REQUIRED: a voucher line must post to exactly one account (line of voucher %s names %s accounts and %s parties)',
                          NEW.voucher_id, account_targets, party_targets),
         HINT = 'Choose one ledger, bank or fixed asset (optionally tagged with one party), or one party.';
     END IF;

     IF NEW.ledger_account_id IS NOT NULL THEN
       SELECT company_id, deleted_at INTO target_company, target_deleted
         FROM ledger_accounts WHERE id = NEW.ledger_account_id;
       IF NOT FOUND OR target_company IS DISTINCT FROM NEW.company_id THEN
         RAISE EXCEPTION USING ERRCODE = '23514',
           MESSAGE = format('LEDGER_ACCOUNT_COMPANY_MISMATCH: ledger account %s does not belong to company %s',
                            NEW.ledger_account_id, NEW.company_id);
       END IF;
       IF target_deleted IS NOT NULL THEN
         RAISE EXCEPTION USING ERRCODE = '23514',
           MESSAGE = format('LEDGER_ACCOUNT_DELETED: ledger account %s is deleted and cannot be posted to',
                            NEW.ledger_account_id);
       END IF;
     END IF;

     IF NEW.bank_account_id IS NOT NULL THEN
       SELECT company_id, deleted_at INTO target_company, target_deleted
         FROM bank_accounts WHERE id = NEW.bank_account_id;
       IF NOT FOUND OR target_company IS DISTINCT FROM NEW.company_id OR target_deleted IS NOT NULL THEN
         RAISE EXCEPTION USING ERRCODE = '23514',
           MESSAGE = format('BANK_ACCOUNT_NOT_POSTABLE: bank account %s is deleted or belongs to another company',
                            NEW.bank_account_id);
       END IF;
     END IF;

     IF NEW.fixed_asset_id IS NOT NULL THEN
       -- Phase 19 (B), v4: a soft-deleted fixed asset (PE7) is not postable;
       -- read through to_jsonb so a database without the column still works.
       SELECT fa.company_id, (to_jsonb(fa)->>'deleted_at') INTO target_company, target_deleted
         FROM fixed_assets fa WHERE fa.id = NEW.fixed_asset_id;
       IF NOT FOUND OR target_company IS DISTINCT FROM NEW.company_id THEN
         RAISE EXCEPTION USING ERRCODE = '23514',
           MESSAGE = format('FIXED_ASSET_COMPANY_MISMATCH: fixed asset %s does not belong to company %s',
                            NEW.fixed_asset_id, NEW.company_id);
       END IF;
       IF target_deleted IS NOT NULL THEN
         RAISE EXCEPTION USING ERRCODE = '23514',
           MESSAGE = format('FIXED_ASSET_DELETED: fixed asset %s is deleted and cannot be posted to', NEW.fixed_asset_id);
       END IF;
     END IF;

     IF NEW.customer_id IS NOT NULL THEN
       SELECT company_id INTO target_company FROM customers WHERE id = NEW.customer_id;
       IF NOT FOUND OR target_company IS DISTINCT FROM NEW.company_id THEN
         RAISE EXCEPTION USING ERRCODE = '23514',
           MESSAGE = format('CUSTOMER_COMPANY_MISMATCH: customer %s does not belong to company %s',
                            NEW.customer_id, NEW.company_id);
       END IF;
     END IF;

     IF NEW.employee_id IS NOT NULL THEN
       SELECT company_id INTO target_company FROM employees WHERE id = NEW.employee_id;
       IF target_company IS DISTINCT FROM NEW.company_id THEN
         RAISE EXCEPTION USING ERRCODE = '23514',
           MESSAGE = format('EMPLOYEE_COMPANY_MISMATCH: employee %s does not belong to company %s',
                            NEW.employee_id, NEW.company_id);
       END IF;
     END IF;

     IF NEW.factory_supplier_id IS NOT NULL THEN
       SELECT company_id INTO target_company FROM factory_suppliers WHERE id = NEW.factory_supplier_id;
       IF target_company IS DISTINCT FROM NEW.company_id THEN
         RAISE EXCEPTION USING ERRCODE = '23514',
           MESSAGE = format('FACTORY_SUPPLIER_COMPANY_MISMATCH: factory supplier %s does not belong to company %s',
                            NEW.factory_supplier_id, NEW.company_id);
       END IF;
     END IF;

     IF NEW.supplier_id IS NOT NULL THEN
       SELECT company_id INTO target_company FROM suppliers WHERE id = NEW.supplier_id;
       IF target_company IS DISTINCT FROM NEW.company_id THEN
         -- Group suppliers are shared between a parent and its subsidiaries in
         -- both directions (subsidiary POs, and the parent's side of an
         -- intercompany PO); anything outside that parent/child pair is refused.
         SELECT parent_company_id INTO parent_company FROM companies WHERE id = NEW.company_id;
         IF NOT (
              (parent_company IS NOT NULL AND target_company = parent_company)
              OR EXISTS (SELECT 1 FROM companies c WHERE c.id = target_company AND c.parent_company_id = NEW.company_id)
            ) THEN
           RAISE EXCEPTION USING ERRCODE = '23514',
             MESSAGE = format('SUPPLIER_COMPANY_MISMATCH: supplier %s belongs to neither company %s nor its parent or subsidiaries',
                              NEW.supplier_id, NEW.company_id);
         END IF;
       END IF;
     END IF;

     RETURN NEW;
   END
   $function$
","publicExecute":true,"comment":"2026-10-ledger-integrity-v4"}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_vouchers_actor_columns()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     v_actor text := erp_audit_current_actor();
   BEGIN
     IF TG_OP = 'INSERT' THEN
       IF v_actor <> 'unknown' OR NULLIF(btrim(COALESCE(NEW.created_by, '')), '') IS NULL THEN
         NEW.created_by := v_actor;
       END IF;
       NEW.updated_by := NULL;
       NEW.deleted_by := CASE WHEN NEW.deleted_at IS NOT NULL THEN v_actor END;
       NEW.original_voucher_number := NULL;
       RETURN NEW;
     END IF;
     NEW.created_by := OLD.created_by;
     NEW.updated_by := OLD.updated_by;
     IF NEW.deleted_at IS NULL THEN
       NEW.deleted_by := NULL;
     ELSIF OLD.deleted_at IS NULL THEN
       NEW.deleted_by := v_actor;
     ELSE
       NEW.deleted_by := OLD.deleted_by;
     END IF;
     IF OLD.original_voucher_number IS NOT NULL THEN
       NEW.original_voucher_number := OLD.original_voucher_number;
     ELSIF NEW.voucher_number ~ '~DEL[0-9]+$' AND OLD.voucher_number !~ '~DEL[0-9]+$' THEN
       NEW.original_voucher_number := OLD.voucher_number;
     ELSE
       NEW.original_voucher_number := NULL;
     END IF;
     IF NEW IS DISTINCT FROM OLD THEN
       NEW.updated_by := v_actor;
     END IF;
     RETURN NEW;
   END
   $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_vouchers_balance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   BEGIN
     PERFORM erp_voucher_balance_check(NEW.id);
     RETURN NULL;
   END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_vouchers_closed_period_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   DECLARE
     financial_change boolean := true;
   BEGIN
     IF TG_OP = 'UPDATE' THEN
       financial_change :=
         (NEW.company_id, NEW.voucher_type, NEW.voucher_date, NEW.effective_date, NEW.total_amount,
          NEW.currency, NEW.exchange_rate, NEW.optional, NEW.deleted_at)
         IS DISTINCT FROM
         (OLD.company_id, OLD.voucher_type, OLD.voucher_date, OLD.effective_date, OLD.total_amount,
          OLD.currency, OLD.exchange_rate, OLD.optional, OLD.deleted_at);
     END IF;

     IF NOT financial_change THEN
       RETURN NEW;
     END IF;

     IF TG_OP IN ('UPDATE', 'DELETE') THEN
       PERFORM erp_assert_accounting_date_open(OLD.company_id, OLD.voucher_date);
       PERFORM erp_assert_accounting_date_open(OLD.company_id, OLD.effective_date);
     END IF;
     IF TG_OP IN ('INSERT', 'UPDATE') THEN
       PERFORM erp_assert_accounting_date_open(NEW.company_id, NEW.voucher_date);
       PERFORM erp_assert_accounting_date_open(NEW.company_id, NEW.effective_date);
     END IF;

     IF TG_OP = 'DELETE' THEN
       RETURN OLD;
     END IF;
     RETURN NEW;
   END
   $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.erp_vouchers_history_marker_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
   BEGIN
     IF TG_OP = 'INSERT' THEN
       -- A new voucher is never history, whatever the writer (or an import) sends.
       NEW.balance_guard_exempt_history := false;
     ELSIF NEW.balance_guard_exempt_history IS DISTINCT FROM OLD.balance_guard_exempt_history THEN
       RAISE EXCEPTION 'Voucher % history marker is set once, when the balance guard is installed, and cannot change',
         OLD.voucher_number USING ERRCODE = '23514';
     ELSIF OLD.posted_by_engine AND NOT NEW.posted_by_engine THEN
       RAISE EXCEPTION 'Voucher % was posted by the central posting engine; that marker cannot be cleared',
         OLD.voucher_number USING ERRCODE = '23514';
     END IF;
     RETURN NEW;
   END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_default_new_adjustment_valuation_basis()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT'
     AND UPPER(NEW.type) = 'ADD'
     AND NEW.supplier_id IS NOT NULL
     AND NEW.valuation_basis IS NULL THEN
    NEW.valuation_basis := 'QUANTITY_ONLY';
  END IF;
  RETURN NEW;
END;
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_financial_guard_charge_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  parent_id BIGINT;
  parent_status VARCHAR(16);
BEGIN
  IF TG_OP = 'DELETE' THEN
    parent_id := OLD.financial_id;
  ELSE
    parent_id := NEW.financial_id;
  END IF;

  SELECT status INTO parent_status
    FROM factory_dispatch_trip_financials WHERE id = parent_id FOR UPDATE;

  IF parent_status IS NULL OR parent_status NOT IN ('DRAFT', 'REVERSED') THEN
    RAISE EXCEPTION 'Only draft/reversed trip charges can be modified';
  END IF;

  IF TG_OP = 'UPDATE' OR TG_OP = 'DELETE' THEN
    IF OLD.locked_at IS NOT NULL THEN
      RAISE EXCEPTION 'A previously posted trip charge cannot be changed';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.financial_id <> OLD.financial_id OR NEW.company_id <> OLD.company_id OR
       NEW.order_id <> OLD.order_id OR NEW.dispatch_id <> OLD.dispatch_id OR
       NEW.revision <> OLD.revision THEN
      RAISE EXCEPTION 'Trip charge ownership and revision cannot be changed';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_financial_prevent_history_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'Factory dispatch financial historical rows are append-only';
END;
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_guard_final_commercial_lines()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_order INTEGER;
BEGIN
  IF TG_OP<>'INSERT' THEN
    target_order := OLD.order_id;
    IF EXISTS(
      SELECT 1 FROM public.factory_dispatch_order_consolidations c
       WHERE c.order_id=target_order AND c.status='FINALIZED'
    ) THEN
      RAISE EXCEPTION 'Finalized Factory dispatch commercial invoice lines are immutable';
    END IF;
  END IF;
  IF TG_OP<>'DELETE' THEN
    target_order := NEW.order_id;
    IF EXISTS(
      SELECT 1 FROM public.factory_dispatch_order_consolidations c
       WHERE c.order_id=target_order AND c.status='FINALIZED'
    ) THEN
      RAISE EXCEPTION 'Cannot insert or move lines into a finalized Factory dispatch invoice';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END; $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_guard_final_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.status='FINALIZED' THEN
      RAISE EXCEPTION 'Finalized Factory dispatch combined invoice is immutable';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.status='FINALIZED' THEN
    IF NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'Finalized Factory dispatch combined invoice cannot be modified or reversed by legacy workflows';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.status='FINALIZED' THEN
    IF OLD.status<>'DRAFT' OR OLD.reconciled_at IS NULL
       OR OLD.invoice_number IS NOT NULL OR OLD.finalized_at IS NOT NULL
       OR NEW.invoice_number IS NULL OR NEW.finalized_at IS NULL
       OR NEW.finalized_by_user_id IS NULL
    THEN
      RAISE EXCEPTION 'Combined invoice requires one signed DRAFT -> FINALIZED transition';
    END IF;
  END IF;
  RETURN NEW;
END; $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_guard_final_vouchers()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  protected_old INTEGER;
  protected_new INTEGER;
  old_company INTEGER;
  new_company INTEGER;
BEGIN
  IF TG_TABLE_NAME='voucher_entries' THEN
    IF TG_OP<>'INSERT' THEN protected_old:=OLD.voucher_id; END IF;
    IF TG_OP<>'DELETE' THEN protected_new:=NEW.voucher_id; END IF;
  ELSIF TG_TABLE_NAME='accounting_posting_requests' THEN
    IF TG_OP<>'INSERT' THEN protected_old:=OLD.voucher_id; END IF;
    IF TG_OP<>'DELETE' THEN protected_new:=NEW.voucher_id; END IF;
  ELSE
    IF TG_OP<>'INSERT' THEN protected_old:=OLD.id; END IF;
    IF TG_OP<>'DELETE' THEN protected_new:=NEW.id; END IF;
  END IF;

  IF protected_old IS NOT NULL THEN
    SELECT company_id INTO old_company FROM vouchers WHERE id=protected_old;
    IF old_company IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.factory_dispatch_order_consolidations c
       WHERE c.company_id=old_company AND c.status='FINALIZED'
         AND c.finalization_details->'voucherIds' @> jsonb_build_array(protected_old)
    ) THEN
      RAISE EXCEPTION 'Finalized Factory combined-invoice source voucher is immutable';
    END IF;
  END IF;
  -- Also reject inserting/moving entries into a protected voucher.
  IF protected_new IS NOT NULL AND protected_new IS DISTINCT FROM protected_old THEN
    SELECT company_id INTO new_company FROM vouchers WHERE id=protected_new;
    IF new_company IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.factory_dispatch_order_consolidations c
       WHERE c.company_id=new_company AND c.status='FINALIZED'
         AND c.finalization_details->'voucherIds' @> jsonb_build_array(protected_new)
    ) THEN
      RAISE EXCEPTION 'Cannot insert entries into an immutable Factory combined-invoice voucher';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END; $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_guard_order_bale_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    DECLARE
      old_company_id INTEGER;
      order_status TEXT;
      order_invoice_number TEXT;
      has_live BOOLEAN;
      is_posted_bale BOOLEAN;
    BEGIN
      IF TG_OP = 'INSERT' THEN
        SELECT company_id, status, invoice_number
          INTO old_company_id, order_status, order_invoice_number
          FROM customer_orders WHERE id = NEW.order_id;
        IF old_company_id IS NULL THEN RETURN NEW; END IF;
        -- Financially completed orders remain immutable. Earlier POSTED trucks do
        -- not lock future additions to an unfinished loading; existing posted
        -- bales, their prices, and their truck evidence are still guarded below.
        SELECT EXISTS(
          SELECT 1 FROM factory_dispatch_trip_financials
           WHERE company_id=old_company_id AND order_id=NEW.order_id
             AND status = 'CONSOLIDATED'
        ) INTO has_live;
        IF has_live THEN
          RAISE EXCEPTION 'Cannot add bales after the dispatch invoice is consolidated';
        END IF;
        SELECT EXISTS(
          SELECT 1 FROM factory_dispatch_trip_financials
           WHERE company_id=old_company_id AND order_id=NEW.order_id
             AND status = 'POSTED'
        ) INTO has_live;
        IF has_live AND (
          order_status NOT IN ('DRAFT', 'LOADING', 'PENDING_VERIFICATION')
          OR order_invoice_number IS NOT NULL
        ) THEN
          RAISE EXCEPTION 'Cannot add bales to a completed dispatch loading';
        END IF;
        RETURN NEW;
      END IF;

      SELECT company_id INTO old_company_id FROM customer_orders WHERE id = OLD.order_id;
      IF old_company_id IS NULL THEN RETURN OLD; END IF;
      SELECT EXISTS(
        SELECT 1 FROM factory_dispatch_trip_financials
         WHERE company_id=old_company_id AND order_id=OLD.order_id
           AND status IN ('POSTED','CONSOLIDATED')
      ) INTO has_live;
      IF NOT has_live THEN
        IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
      END IF;
      SELECT EXISTS (
        SELECT 1 FROM factory_dispatch_trip_financial_bales b
          JOIN factory_dispatch_trip_financials f
            ON f.id=b.financial_id AND f.company_id=b.company_id
           AND f.order_id=b.order_id AND f.dispatch_id=b.dispatch_id
         WHERE b.company_id=old_company_id AND b.order_id=OLD.order_id
           AND b.bale_id=OLD.bale_id AND b.snapshot_revision=f.snapshot_revision
           AND f.status IN ('POSTED','CONSOLIDATED')
      ) INTO is_posted_bale;

      IF TG_OP = 'UPDATE' THEN
        -- No silent valuation or identity changes while trip balances exist;
        -- only the later approved consolidation procedure can remove the hold.
        RAISE EXCEPTION 'Loading bale records are locked while dispatch trips have live financial postings';
      END IF;
      IF is_posted_bale THEN
        RAISE EXCEPTION 'Financially posted dispatch bale cannot be removed from Pending Loading';
      END IF;
      -- Unshipped/unscanned bale removals remain possible through the authorized
      -- reconciliation endpoint, which checks status and approver on the server.
      RETURN OLD;
    END;
    $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_guard_posted_physical_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  c INTEGER;
  o INTEGER;
  d BIGINT;
  posted BOOLEAN;
BEGIN
  IF TG_TABLE_NAME = 'factory_loading_dispatches' THEN
    IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
    c := OLD.company_id; o := OLD.order_id; d := OLD.id;
  ELSIF TG_TABLE_NAME = 'factory_loading_dispatch_scans' THEN
    IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
    c := OLD.company_id; o := OLD.order_id; d := OLD.dispatch_id;
  ELSE
    IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
    c := OLD.company_id; o := OLD.order_id; d := OLD.dispatch_id;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM factory_dispatch_trip_financials
     WHERE company_id=c AND order_id=o AND dispatch_id=d
       AND status IN ('POSTED','CONSOLIDATED')
  ) INTO posted;
  IF posted THEN
    IF TG_TABLE_NAME = 'factory_loading_dispatches' AND TG_OP = 'UPDATE' THEN
      IF NEW.status = OLD.status AND NEW.closed_at IS NOT DISTINCT FROM OLD.closed_at
         AND NEW.closed_by_user_id IS NOT DISTINCT FROM OLD.closed_by_user_id THEN
        RETURN NEW;
      END IF;
    END IF;
    RAISE EXCEPTION 'Cannot alter signed physical dispatch evidence after financial posting';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_guard_posted_vouchers()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    protected_voucher_id INTEGER;
    protected_company_id INTEGER;
    linked BOOLEAN;
BEGIN
    IF TG_TABLE_NAME = 'voucher_entries' THEN
        IF TG_OP = 'INSERT' THEN
            protected_voucher_id := NEW.voucher_id;
        ELSE
            protected_voucher_id := OLD.voucher_id;
        END IF;

        SELECT company_id INTO protected_company_id
        FROM vouchers
        WHERE id = protected_voucher_id;

    ELSIF TG_TABLE_NAME = 'accounting_posting_requests' THEN
        IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
        protected_voucher_id := OLD.voucher_id;
        protected_company_id := OLD.company_id;

    ELSIF TG_TABLE_NAME = 'vouchers' THEN
        IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
        protected_voucher_id := OLD.id;
        protected_company_id := OLD.company_id;

    ELSE
        RAISE EXCEPTION
            'Unsupported dispatch voucher trigger table: %',
            TG_TABLE_NAME;
    END IF;

    IF protected_voucher_id IS NOT NULL
       AND protected_company_id IS NOT NULL THEN

        SELECT EXISTS (
            SELECT 1
            FROM factory_dispatch_trip_postings p
            WHERE p.company_id = protected_company_id
              AND p.voucher_ids @>
                  jsonb_build_array(protected_voucher_id)
        ) INTO linked;

        IF linked THEN
            RAISE EXCEPTION
                'Source-owned Factory dispatch voucher cannot be changed or retired; use trip financial correction';
        END IF;
    END IF;

    -- Critical fix: access NEW.voucher_id ONLY on voucher_entries.
    IF TG_TABLE_NAME = 'voucher_entries' THEN
        IF TG_OP = 'UPDATE' THEN
            IF NEW.voucher_id IS DISTINCT FROM OLD.voucher_id THEN

                SELECT company_id INTO protected_company_id
                FROM vouchers
                WHERE id = NEW.voucher_id;

                IF EXISTS (
                    SELECT 1
                    FROM factory_dispatch_trip_postings p
                    WHERE p.company_id = protected_company_id
                      AND p.voucher_ids @>
                          jsonb_build_array(NEW.voucher_id)
                ) THEN
                    RAISE EXCEPTION
                        'Cannot transfer an entry into a finalized Factory dispatch voucher';
                END IF;
            END IF;
        END IF;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_guard_signed_consolidation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.reconciled_at IS NOT NULL THEN
      RAISE EXCEPTION 'Signed Factory dispatch reconciliation cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.reconciled_at IS NOT NULL THEN
    IF NEW.reconciled_at IS DISTINCT FROM OLD.reconciled_at
       OR NEW.reconciled_by_user_id IS DISTINCT FROM OLD.reconciled_by_user_id
       OR NEW.reconciliation_reason IS DISTINCT FROM OLD.reconciliation_reason
       OR NEW.reconciliation_fingerprint IS DISTINCT FROM OLD.reconciliation_fingerprint
       OR NEW.reconciliation_snapshot IS DISTINCT FROM OLD.reconciliation_snapshot
       OR NEW.included_posting_ids IS DISTINCT FROM OLD.included_posting_ids
       OR NEW.goods_subtotal IS DISTINCT FROM OLD.goods_subtotal
       OR NEW.billable_charges_total IS DISTINCT FROM OLD.billable_charges_total
       OR NEW.discount_total IS DISTINCT FROM OLD.discount_total
       OR NEW.customer_total IS DISTINCT FROM OLD.customer_total
    THEN
      RAISE EXCEPTION 'Signed Factory dispatch reconciliation evidence is immutable';
    END IF;
  END IF;
  RETURN NEW;
END; $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_guard_signed_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_order INTEGER;
  target_company INTEGER;
  is_signed BOOLEAN;
  new_target_signed BOOLEAN;
BEGIN
  IF TG_TABLE_NAME='factory_loading_dispatches'
     OR TG_TABLE_NAME='factory_loading_dispatch_scans'
     OR TG_TABLE_NAME='factory_loading_dispatch_closure_history' THEN
    IF TG_OP='INSERT' THEN
      target_company:=NEW.company_id;
      target_order:=NEW.order_id;
    ELSE
      target_company:=OLD.company_id;
      target_order:=OLD.order_id;
    END IF;
  ELSE
    IF TG_OP='INSERT' THEN target_order:=NEW.order_id;
    ELSE target_order:=OLD.order_id;
    END IF;
    SELECT company_id INTO target_company FROM customer_orders WHERE id=target_order;
  END IF;
  SELECT EXISTS(
    SELECT 1 FROM factory_dispatch_order_consolidations
     WHERE company_id=target_company AND order_id=target_order
       AND reconciled_at IS NOT NULL AND status IN ('DRAFT','FINALIZED')
  ) INTO is_signed;
  IF is_signed THEN
    -- Phase 8 may link a previously unposted original loading charge to its
    -- newly created customer voucher *during DRAFT consolidation only*.
    -- Amount, ledger mapping, name and order ownership remain immutable.
    IF TG_TABLE_NAME='customer_order_charges' AND TG_OP='UPDATE'
       AND OLD.voucher_id IS NULL AND NEW.voucher_id IS NOT NULL
       AND NEW.id=OLD.id AND NEW.order_id=OLD.order_id
       AND NEW.name IS NOT DISTINCT FROM OLD.name
       AND NEW.amount IS NOT DISTINCT FROM OLD.amount
       AND NEW.charge_type IS NOT DISTINCT FROM OLD.charge_type
       AND NEW.ledger_account_id IS NOT DISTINCT FROM OLD.ledger_account_id
       AND EXISTS (
         SELECT 1 FROM factory_dispatch_order_consolidations c
          WHERE c.company_id=target_company AND c.order_id=target_order
            AND c.reconciled_at IS NOT NULL AND c.status='DRAFT'
       )
       AND EXISTS (
         SELECT 1 FROM vouchers v
         JOIN customer_orders co ON co.id=NEW.order_id AND co.company_id=target_company
          WHERE v.id=NEW.voucher_id AND v.company_id=target_company
            AND v.deleted_at IS NULL AND COALESCE(v.optional,FALSE)=FALSE
            AND EXISTS(
              SELECT 1 FROM voucher_entries ve
               WHERE ve.voucher_id=v.id AND ve.customer_id=co.customer_id
                 AND ve.debit_amount=OLD.amount
            )
            AND EXISTS(
              SELECT 1 FROM voucher_entries ve
               WHERE ve.voucher_id=v.id AND ve.ledger_account_id=OLD.ledger_account_id
                 AND ve.credit_amount=OLD.amount
            )
       )
    THEN RETURN NEW;
    END IF;
    RAISE EXCEPTION 'This order has a signed all-truck reconciliation; change of scanned/loaded/charge evidence is forbidden';
  END IF;
  -- Also reject moving a row FROM an unsigned order INTO a signed order.
  -- Without checking NEW ownership, UPDATE order_id could evade an OLD-only
  -- guard and pollute the signed bale/scan/charge evidence.
  IF TG_OP='UPDATE' THEN
    IF TG_TABLE_NAME='factory_loading_dispatches'
       OR TG_TABLE_NAME='factory_loading_dispatch_scans'
       OR TG_TABLE_NAME='factory_loading_dispatch_closure_history' THEN
      SELECT EXISTS(
        SELECT 1 FROM factory_dispatch_order_consolidations
         WHERE company_id=NEW.company_id AND order_id=NEW.order_id
           AND reconciled_at IS NOT NULL AND status IN ('DRAFT','FINALIZED')
      ) INTO new_target_signed;
    ELSE
      SELECT EXISTS(
        SELECT 1 FROM factory_dispatch_order_consolidations c
        JOIN customer_orders o ON o.id=NEW.order_id
         WHERE c.company_id=o.company_id AND c.order_id=NEW.order_id
           AND c.reconciled_at IS NOT NULL AND c.status IN ('DRAFT','FINALIZED')
      ) INTO new_target_signed;
    END IF;
    IF new_target_signed THEN
      RAISE EXCEPTION 'Cannot move barcode, trip or charge evidence into a signed Factory order';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END; $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_dispatch_guard_signed_financials()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  signed BOOLEAN;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM factory_dispatch_order_consolidations
     WHERE company_id=OLD.company_id AND order_id=OLD.order_id
       AND reconciled_at IS NOT NULL AND status IN ('DRAFT','FINALIZED')
  ) INTO signed;
  IF signed THEN
    IF TG_OP='DELETE' THEN
      RAISE EXCEPTION 'Signed order financials cannot be removed';
    END IF;
    IF TG_OP='UPDATE' AND NEW.status='CONSOLIDATED'
       AND OLD.status='POSTED'
       AND NEW.goods_subtotal IS NOT DISTINCT FROM OLD.goods_subtotal
       AND NEW.billable_charges_total IS NOT DISTINCT FROM OLD.billable_charges_total
       AND NEW.discount_total IS NOT DISTINCT FROM OLD.discount_total
       AND NEW.customer_total IS NOT DISTINCT FROM OLD.customer_total
       AND NEW.source_fingerprint IS NOT DISTINCT FROM OLD.source_fingerprint
       AND NEW.manifest_fingerprint IS NOT DISTINCT FROM OLD.manifest_fingerprint
       AND NEW.snapshot_revision IS NOT DISTINCT FROM OLD.snapshot_revision
       AND NEW.posting_revision IS NOT DISTINCT FROM OLD.posting_revision
    THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Signed dispatch financial postings cannot be edited or reversed';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END; $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_edge_operator_decide_conflict(p_site uuid, p_stream text, p_sequence bigint, p_decision text, p_user_id text, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
    DECLARE
      v_conflict record;
      v_name text;
      v_id bigint;
    BEGIN
      IF p_decision IS NULL OR p_decision NOT IN ('reject-event', 'approve-override')
         OR length(btrim(coalesce(p_reason, ''))) < 10 THEN
        RAISE EXCEPTION 'PHASE9_CONFLICT_DECISION_INVALID' USING ERRCODE = '22023';
      END IF;
      SELECT id, company_id INTO v_conflict
        FROM factory_edge_event_conflicts
       WHERE site_id = p_site AND stream = p_stream AND sequence = p_sequence
       ORDER BY id DESC LIMIT 1;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'PHASE9_CONFLICT_NOT_FOUND' USING ERRCODE = '02000';
      END IF;
      SELECT u.username INTO v_name
        FROM users u
        JOIN user_company_roles r ON r.user_id = u.id AND r.company_id = v_conflict.company_id
       WHERE u.id = p_user_id AND u.active = true AND r.role IN ('Admin', 'Developer')
       LIMIT 1;
      IF v_name IS NULL THEN
        RAISE EXCEPTION 'PHASE9_REVIEWER_NOT_AUTHORIZED' USING ERRCODE = '42501';
      END IF;
      INSERT INTO factory_edge_event_conflict_decisions
        (site_id, stream, sequence, conflict_id, decision, decided_by, reason)
      VALUES (p_site, p_stream, p_sequence, v_conflict.id, p_decision, v_name, btrim(p_reason))
      RETURNING conflict_id INTO v_id;
      RETURN v_id;
    END
    $function$
","publicExecute":false,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_edge_operator_sync_control(p_site uuid, p_company integer, p_user_id text, p_action text, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
    DECLARE
      v_name text;
      v_id bigint;
    BEGIN
      IF p_action IS NULL OR p_action NOT IN ('pause', 'resume')
         OR length(btrim(coalesce(p_reason, ''))) < 10 THEN
        RAISE EXCEPTION 'PHASE10_SYNC_CONTROL_INVALID' USING ERRCODE = '22023';
      END IF;
      SELECT u.username INTO v_name
        FROM users u
        JOIN user_company_roles r ON r.user_id = u.id AND r.company_id = p_company
       WHERE u.id = p_user_id AND u.active = true AND r.role IN ('Admin', 'Owner')
       LIMIT 1;
      IF v_name IS NULL THEN
        RAISE EXCEPTION 'PHASE10_OPERATOR_NOT_AUTHORIZED' USING ERRCODE = '42501';
      END IF;
      INSERT INTO factory_edge_sync_control_log (site_id, action, operator_name, reason)
      VALUES (p_site, p_action, v_name, btrim(p_reason))
      RETURNING id INTO v_id;
      RETURN v_id;
    END
    $function$
","publicExecute":false,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_pressing_confirmations_protect()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Pressing confirmations cannot be deleted';
  END IF;
  IF OLD.voided_at IS NOT NULL
     OR NEW.voided_at IS NULL
     OR NEW.voided_by IS NULL
     OR (to_jsonb(NEW) - 'voided_at' - 'voided_by') IS DISTINCT FROM (to_jsonb(OLD) - 'voided_at' - 'voided_by')
  THEN
    RAISE EXCEPTION 'Only a single audited void may update a pressing confirmation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM factory_pressing_corrections c
    WHERE c.company_id = OLD.company_id
      AND c.confirmation_id = OLD.id
      AND c.action = 'VOID'
      AND c.supervisor_user_id = NEW.voided_by
  ) THEN
    RAISE EXCEPTION 'A supervisor correction event must be recorded before voiding a pressing confirmation';
  END IF;
  RETURN NEW;
END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.factory_resolve_mix_source_inventory_supplier()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  resolved_supplier_id INTEGER;
  source_company_id INTEGER;
  container_supplier_id INTEGER;
BEGIN
  SELECT company_id
    INTO source_company_id
    FROM factory_mix_batches
   WHERE id = NEW.mix_batch_id
     AND deleted_at IS NULL;

  IF source_company_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'MIX_BATCH_COMPANY_UNRESOLVED: source batch is missing or deleted';
  END IF;

  IF NEW.source_batch_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM factory_mix_batches upstream
      WHERE upstream.id = NEW.source_batch_id
        AND upstream.company_id = source_company_id
        AND upstream.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'UPSTREAM_BATCH_COMPANY_MISMATCH: source batch belongs to another company or is missing';
    END IF;
    NEW.inventory_supplier_id := NULL;
    RETURN NEW;
  END IF;

  resolved_supplier_id := NEW.inventory_supplier_id;

  IF resolved_supplier_id IS NULL AND NEW.supplier_id IS NOT NULL THEN
    resolved_supplier_id := NEW.supplier_id;
  END IF;

  IF NEW.container_id IS NOT NULL THEN
    SELECT supplier_id
      INTO container_supplier_id
      FROM factory_containers
     WHERE id = NEW.container_id
       AND company_id = source_company_id
       AND deleted_at IS NULL;

    IF container_supplier_id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'CONTAINER_INVENTORY_SUPPLIER_UNRESOLVED: source container is missing, belongs to another company, or has no supplier';
    END IF;

    IF resolved_supplier_id IS NULL THEN
      resolved_supplier_id := container_supplier_id;
    ELSIF resolved_supplier_id <> container_supplier_id THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'CONTAINER_INVENTORY_SUPPLIER_CONFLICT: source owner does not match the container supplier';
    END IF;
  END IF;

  IF resolved_supplier_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'INVENTORY_SUPPLIER_UNRESOLVED: non-batch raw-material source has no supplier owner';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM factory_suppliers
    WHERE id = resolved_supplier_id
      AND company_id = source_company_id
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'INVENTORY_SUPPLIER_COMPANY_MISMATCH: supplier owner belongs to another company';
  END IF;

  IF NEW.supplier_id IS NOT NULL AND NEW.supplier_id <> resolved_supplier_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'INVENTORY_SUPPLIER_CONFLICT: pricing supplier and inventory owner disagree';
  END IF;

  NEW.inventory_supplier_id := resolved_supplier_id;
  RETURN NEW;
END;
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.fiscal_review_assert_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
 DECLARE a RECORD; o RECORD; c RECORD; v RECORD;
 BEGIN
  SELECT * INTO a FROM accounting_fiscal_review_signoffs
   WHERE id=NEW.accounting_signoff_id AND company_id=NEW.company_id;
  SELECT * INTO o FROM accounting_fiscal_review_signoffs
   WHERE id=NEW.owner_signoff_id AND company_id=NEW.company_id;
  SELECT * INTO c FROM fiscal_period_closures
   WHERE id=NEW.fiscal_closure_id AND company_id=NEW.company_id;
  SELECT * INTO v FROM vouchers
   WHERE id=NEW.closing_voucher_id AND company_id=NEW.company_id;
  IF a.id IS NULL OR o.id IS NULL OR c.id IS NULL OR v.id IS NULL
     OR a.review_kind<>'ACCOUNTING' OR o.review_kind<>'OWNER'
     OR a.reviewer_id=o.reviewer_id
     OR a.revoked_at IS NOT NULL OR o.revoked_at IS NOT NULL
     OR a.evidence_hash<>NEW.evidence_hash OR o.evidence_hash<>NEW.evidence_hash
     OR a.period_start_date<>c.period_start_date OR o.period_start_date<>c.period_start_date
     OR a.period_end_date<>c.period_end_date OR o.period_end_date<>c.period_end_date
     OR a.retained_earnings_account_id<>c.retained_earnings_account_id
     OR o.retained_earnings_account_id<>c.retained_earnings_account_id
     OR c.closing_voucher_id<>NEW.closing_voucher_id THEN
    RAISE EXCEPTION 'FISCAL_REVIEW_EVIDENCE_MISMATCH' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.normalize_voucher_entry_currency_amounts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  voucher_currency text;
  voucher_rate numeric(20, 10);
  raw_debit numeric(20, 6);
  raw_credit numeric(20, 6);
  expected_base_debit numeric(20, 6);
  expected_base_credit numeric(20, 6);
  dual_fields_changed boolean;
BEGIN
  SELECT UPPER(COALESCE(v.currency, 'USD')), v.exchange_rate::numeric
    INTO voucher_currency, voucher_rate
    FROM vouchers v
   WHERE v.id = NEW.voucher_id;

  IF voucher_currency IS NULL THEN
    RAISE EXCEPTION 'Voucher % not found while normalizing voucher entry', NEW.voucher_id;
  END IF;

  IF TG_OP = 'INSERT' THEN
    dual_fields_changed := true;
  ELSE
    dual_fields_changed :=
      NEW.transaction_currency IS DISTINCT FROM OLD.transaction_currency
      OR NEW.transaction_debit_amount IS DISTINCT FROM OLD.transaction_debit_amount
      OR NEW.transaction_credit_amount IS DISTINCT FROM OLD.transaction_credit_amount
      OR NEW.base_debit_amount IS DISTINCT FROM OLD.base_debit_amount
      OR NEW.base_credit_amount IS DISTINCT FROM OLD.base_credit_amount
      OR NEW.historical_exchange_rate IS DISTINCT FROM OLD.historical_exchange_rate
      OR NEW.rate_convention IS DISTINCT FROM OLD.rate_convention;
  END IF;

  -- Legacy update callers still submit debit_amount/credit_amount. Once a row is
  -- normalized, interpret those changed values as NEW transaction-currency amounts
  -- and recompute historical base using the row's already locked rate/convention.
  IF TG_OP = 'UPDATE'
     AND OLD.transaction_currency IS NOT NULL
     AND NOT dual_fields_changed
     AND (NEW.debit_amount IS DISTINCT FROM OLD.debit_amount
          OR NEW.credit_amount IS DISTINCT FROM OLD.credit_amount) THEN
    raw_debit := COALESCE(NEW.debit_amount, 0)::numeric;
    raw_credit := COALESCE(NEW.credit_amount, 0)::numeric;

    IF raw_debit < 0 OR raw_credit < 0 THEN
      RAISE EXCEPTION 'Voucher entry amounts cannot be negative';
    END IF;
    IF raw_debit > 0 AND raw_credit > 0 THEN
      RAISE EXCEPTION 'Voucher entry cannot contain both a debit and a credit amount';
    END IF;
    IF raw_debit = 0 AND raw_credit = 0 THEN
      RAISE EXCEPTION 'Voucher entry must contain a debit or credit amount';
    END IF;

    NEW.transaction_currency := CASE WHEN UPPER(OLD.transaction_currency) = 'XOF' THEN 'CFA' ELSE UPPER(OLD.transaction_currency) END;
    NEW.transaction_debit_amount := raw_debit;
    NEW.transaction_credit_amount := raw_credit;
    NEW.historical_exchange_rate := OLD.historical_exchange_rate;
    NEW.rate_convention := OLD.rate_convention;

    IF NEW.rate_convention = 'IDENTITY' THEN
      NEW.base_debit_amount := raw_debit;
      NEW.base_credit_amount := raw_credit;
    ELSIF NEW.rate_convention = 'TRANSACTION_PER_BASE' THEN
      IF NEW.historical_exchange_rate IS NULL OR NEW.historical_exchange_rate <= 0 THEN
        RAISE EXCEPTION 'TRANSACTION_PER_BASE requires a positive historical rate';
      END IF;
      NEW.base_debit_amount := ROUND(raw_debit / NEW.historical_exchange_rate, 6);
      NEW.base_credit_amount := ROUND(raw_credit / NEW.historical_exchange_rate, 6);
    ELSIF NEW.rate_convention = 'BASE_PER_TRANSACTION' THEN
      IF NEW.historical_exchange_rate IS NULL OR NEW.historical_exchange_rate <= 0 THEN
        RAISE EXCEPTION 'BASE_PER_TRANSACTION requires a positive historical rate';
      END IF;
      NEW.base_debit_amount := ROUND(raw_debit * NEW.historical_exchange_rate, 6);
      NEW.base_credit_amount := ROUND(raw_credit * NEW.historical_exchange_rate, 6);
    ELSE
      RAISE EXCEPTION 'Unknown voucher-entry rate convention %', NEW.rate_convention;
    END IF;

    NEW.debit_amount := NEW.base_debit_amount;
    NEW.credit_amount := NEW.base_credit_amount;
    RETURN NEW;
  END IF;

  -- Fully normalized application paths remain authoritative, but their fields
  -- are validated so contradictory native/base values cannot be persisted.
  IF NEW.transaction_currency IS NOT NULL
     AND NEW.transaction_debit_amount IS NOT NULL
     AND NEW.transaction_credit_amount IS NOT NULL
     AND NEW.base_debit_amount IS NOT NULL
     AND NEW.base_credit_amount IS NOT NULL
     AND NEW.historical_exchange_rate IS NOT NULL
     AND NEW.rate_convention IS NOT NULL THEN
    NEW.transaction_currency := CASE WHEN UPPER(NEW.transaction_currency) = 'XOF' THEN 'CFA' ELSE UPPER(NEW.transaction_currency) END;
    raw_debit := NEW.transaction_debit_amount::numeric;
    raw_credit := NEW.transaction_credit_amount::numeric;

    IF raw_debit < 0 OR raw_credit < 0 THEN
      RAISE EXCEPTION 'Voucher entry amounts cannot be negative';
    END IF;
    IF raw_debit > 0 AND raw_credit > 0 THEN
      RAISE EXCEPTION 'Voucher entry cannot contain both a debit and a credit amount';
    END IF;
    IF raw_debit = 0 AND raw_credit = 0 THEN
      RAISE EXCEPTION 'Voucher entry must contain a debit or credit amount';
    END IF;

    IF NEW.rate_convention = 'IDENTITY' THEN
      expected_base_debit := raw_debit;
      expected_base_credit := raw_credit;
    ELSIF NEW.rate_convention = 'TRANSACTION_PER_BASE' THEN
      IF NEW.historical_exchange_rate <= 0 THEN
        RAISE EXCEPTION 'TRANSACTION_PER_BASE requires a positive historical rate';
      END IF;
      expected_base_debit := ROUND(raw_debit / NEW.historical_exchange_rate, 6);
      expected_base_credit := ROUND(raw_credit / NEW.historical_exchange_rate, 6);
    ELSIF NEW.rate_convention = 'BASE_PER_TRANSACTION' THEN
      IF NEW.historical_exchange_rate <= 0 THEN
        RAISE EXCEPTION 'BASE_PER_TRANSACTION requires a positive historical rate';
      END IF;
      expected_base_debit := ROUND(raw_debit * NEW.historical_exchange_rate, 6);
      expected_base_credit := ROUND(raw_credit * NEW.historical_exchange_rate, 6);
    ELSE
      RAISE EXCEPTION 'Unknown voucher-entry rate convention %', NEW.rate_convention;
    END IF;

    IF ROUND(NEW.base_debit_amount::numeric, 6) <> expected_base_debit
       OR ROUND(NEW.base_credit_amount::numeric, 6) <> expected_base_credit THEN
      RAISE EXCEPTION
        'Voucher entry native/base amounts do not match the historical rate and convention';
    END IF;

    NEW.debit_amount := expected_base_debit;
    NEW.credit_amount := expected_base_credit;
    RETURN NEW;
  END IF;

  -- Unnormalized legacy insertion/update: the legacy debit/credit values are
  -- interpreted as the original transaction-currency values for USD/CFA only.
  raw_debit := COALESCE(NEW.debit_amount, 0)::numeric;
  raw_credit := COALESCE(NEW.credit_amount, 0)::numeric;

  IF raw_debit < 0 OR raw_credit < 0 THEN
    RAISE EXCEPTION 'Voucher entry amounts cannot be negative';
  END IF;
  IF raw_debit > 0 AND raw_credit > 0 THEN
    RAISE EXCEPTION 'Voucher entry cannot contain both a debit and a credit amount';
  END IF;
  IF raw_debit = 0 AND raw_credit = 0 THEN
    RAISE EXCEPTION 'Voucher entry must contain a debit or credit amount';
  END IF;

  IF voucher_currency = 'USD' THEN
    NEW.transaction_currency := 'USD';
    NEW.transaction_debit_amount := raw_debit;
    NEW.transaction_credit_amount := raw_credit;
    NEW.base_debit_amount := raw_debit;
    NEW.base_credit_amount := raw_credit;
    NEW.historical_exchange_rate := 1.0000000000;
    NEW.rate_convention := 'IDENTITY';
    NEW.debit_amount := raw_debit;
    NEW.credit_amount := raw_credit;
    RETURN NEW;
  END IF;

  IF voucher_currency IN ('CFA', 'XOF') THEN
    IF voucher_rate IS NULL OR voucher_rate <= 0 THEN
      RAISE EXCEPTION 'CFA voucher % requires a positive historical exchange rate', NEW.voucher_id;
    END IF;
    NEW.transaction_currency := 'CFA';
    NEW.transaction_debit_amount := raw_debit;
    NEW.transaction_credit_amount := raw_credit;
    NEW.base_debit_amount := ROUND(raw_debit / voucher_rate, 6);
    NEW.base_credit_amount := ROUND(raw_credit / voucher_rate, 6);
    NEW.historical_exchange_rate := voucher_rate;
    NEW.rate_convention := 'TRANSACTION_PER_BASE';
    NEW.debit_amount := NEW.base_debit_amount;
    NEW.credit_amount := NEW.base_credit_amount;
    RETURN NEW;
  END IF;

  -- Any other currency needs its native amounts, historical rate and convention
  -- from the caller (several factory/supplier rate conventions exist, so the
  -- trigger never guesses one). A NEW line without them (an INSERT, or an UPDATE
  -- that changes its voucher, amounts or transaction currency) is refused. An
  -- existing legacy line whose voucher and amounts are unchanged is left as it is.
  IF TG_OP = 'UPDATE'
     AND NEW.voucher_id IS NOT DISTINCT FROM OLD.voucher_id
     AND NEW.debit_amount IS NOT DISTINCT FROM OLD.debit_amount
     AND NEW.credit_amount IS NOT DISTINCT FROM OLD.credit_amount
     AND NEW.transaction_currency IS NOT DISTINCT FROM OLD.transaction_currency THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION
    'VOUCHER_LINE_NATIVE_AMOUNT_REQUIRED: a % voucher line (voucher %) needs its transaction-currency amounts, historical rate and rate convention',
    voucher_currency, NEW.voucher_id
    USING ERRCODE = '23514';
END;
$function$
","publicExecute":true,"comment":"2026-10-09-001-currency-normalization-v2"}

