{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.retail_snapshot_sale_item_cost()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  resolved_cost numeric(20,6);
BEGIN

  SELECT cost
  INTO resolved_cost
  FROM retail_product_variants
  WHERE id = NEW.variant_id
    AND company_id = NEW.company_id;

  IF resolved_cost IS NULL THEN
    RAISE EXCEPTION
      'Retail variant % does not belong to company %',
      NEW.variant_id,
      NEW.company_id;
  END IF;

  NEW.unit_cost := resolved_cost;

  RETURN NEW;
END;
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.rotate_user_credential_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.password IS DISTINCT FROM OLD.password THEN
    INSERT INTO user_credential_versions(user_id, credential_version, updated_at)
    VALUES (NEW.id, 1, now())
    ON CONFLICT (user_id) DO UPDATE
      SET credential_version = user_credential_versions.credential_version + 1,
          updated_at = now();

    IF to_regclass('public.session') IS NOT NULL THEN
      EXECUTE 'DELETE FROM session WHERE sess->>''userId'' = $1' USING NEW.id;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.set_customer_order_bale_scanned_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE
        restored_at TIMESTAMPTZ;
        restored_match BOOLEAN := FALSE;
        history_has_scanned_at BOOLEAN := FALSE;
      BEGIN
        IF NEW.scanned_at IS NOT NULL THEN
          RETURN NEW;
        END IF;

        IF to_regclass('public.customer_order_bales_history') IS NOT NULL THEN
          SELECT EXISTS (
            SELECT 1
            FROM information_schema.columns
            WHERE table_schema = 'public'
              AND table_name = 'customer_order_bales_history'
              AND column_name = 'scanned_at'
          ) INTO history_has_scanned_at;

          IF history_has_scanned_at THEN
            SELECT h.scanned_at, TRUE
            INTO restored_at, restored_match
            FROM public.customer_order_bales_history h
            WHERE h.order_id = NEW.order_id
              AND h.bale_id = NEW.bale_id
            ORDER BY h.cancelled_at DESC
            LIMIT 1;

            IF restored_match THEN
              NEW.scanned_at := restored_at;
              RETURN NEW;
            END IF;
          END IF;
        END IF;

        IF NEW.scanned_by IS NOT NULL AND btrim(NEW.scanned_by) <> '' THEN
          NEW.scanned_at := CURRENT_TIMESTAMP;
        END IF;
        RETURN NEW;
      END;
      $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.snapshot_bale_recode_items_french()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r record; company_id_value integer;
BEGIN
  IF NULLIF(BTRIM(NEW.product_name_fr), '') IS NULL THEN
    SELECT company_id INTO company_id_value FROM bale_recode_sessions WHERE id = NEW.session_id;
    SELECT * INTO r FROM resolve_factory_product_french_snapshot(company_id_value, NEW.product_id, NEW.article_code);
    NEW.product_name_fr := COALESCE(r.product_name_fr, NULLIF(BTRIM(NEW.product_name), ''), NULLIF(BTRIM(NEW.article_code), ''));
  END IF;
  RETURN NEW;
END;
$function$
