{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.sto_wa_batch_item_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
 BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Frozen approval batch items cannot be deleted'; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.company_id IS DISTINCT FROM OLD.company_id OR
     NEW.batch_id IS DISTINCT FROM OLD.batch_id OR NEW.transfer_id IS DISTINCT FROM OLD.transfer_id OR
     NEW.voucher_number_snapshot IS DISTINCT FROM OLD.voucher_number_snapshot OR
     NEW.item_hash_snapshot IS DISTINCT FROM OLD.item_hash_snapshot OR
     NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Frozen approval batch item evidence cannot be changed';
  END IF;
  RETURN NEW;
 END $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.sync_factory_bale_production_attribution_date()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
     BEGIN
       IF NEW.stock_entry_date IS DISTINCT FROM OLD.stock_entry_date AND NEW.stock_entry_date IS NOT NULL THEN
         UPDATE factory_bale_production_attributions
            SET stock_entry_date = NEW.stock_entry_date
          WHERE bale_id = NEW.id;
       END IF;
       RETURN NEW;
     END;
     $function$
","publicExecute":true,"comment":null}

{"kind":"f","def":"CREATE OR REPLACE FUNCTION public.unified_release_review_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
 BEGIN
  IF TG_OP='DELETE' THEN
   RAISE EXCEPTION 'RELEASE_REVIEW_DELETE_FORBIDDEN' USING ERRCODE='23514';
  END IF;
  IF OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL
   OR (to_jsonb(NEW)-'revoked_at'-'revoked_by'-'revoke_reason')
      IS DISTINCT FROM
      (to_jsonb(OLD)-'revoked_at'-'revoked_by'-'revoke_reason')
   OR NULLIF(TRIM(COALESCE(NEW.revoked_by,'')),'') IS NULL
   OR LENGTH(TRIM(COALESCE(NEW.revoke_reason,'')))<10
  THEN RAISE EXCEPTION 'RELEASE_REVIEW_IMMUTABLE' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END $function$
","publicExecute":true,"comment":null}
